INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('a7ef483f-ef7e-5335-a1db-9cbe9011730f'::uuid, '9d6def35-ee95-597b-8fc3-d33ea6ab0660'::uuid, 'De qui Phèdre est-elle amoureuse ?', 'mcq', '["D’Hippolyte, le fils de son époux Thésée","De Thésée","De Théramène","D’Aricie"]'::jsonb, 0, 'Cet amour est coupable, et il est le nœud de la tragédie.', 1),
    ('44682766-99f5-54fd-b392-dce8cb6b9985'::uuid, '9d6def35-ee95-597b-8fc3-d33ea6ab0660'::uuid, 'Qui accuse Hippolyte auprès de Thésée ?', 'mcq', '["Œnone, la nourrice de Phèdre","Phèdre elle-même","Aricie","Théramène"]'::jsonb, 0, 'Elle ment pour sauver sa maîtresse : le mensonge déclenche la catastrophe.', 2),
    ('43ab8001-607b-5177-979c-8b7d5c22adb9'::uuid, '9d6def35-ee95-597b-8fc3-d33ea6ab0660'::uuid, 'Comment Hippolyte meurt-il ?', 'mcq', '["Tué par un monstre marin envoyé par Neptune","Empoisonné par Phèdre","En duel contre Thésée","Exilé, il meurt de chagrin"]'::jsonb, 0, 'La scène est racontée par Théramène : la bienséance interdit de la montrer.', 3),
    ('d81e5c40-1f00-591e-a604-849e7c196069'::uuid, '9d6def35-ee95-597b-8fc3-d33ea6ab0660'::uuid, 'Quelle divinité poursuit Phèdre ?', 'mcq', '["Vénus","Junon","Diane","Minerve"]'::jsonb, 0, '« C’est Vénus tout entière à sa proie attachée. »', 4),
    ('043f2b0e-0001-5dfd-9eb7-5327e8f0bdbb'::uuid, '9d6def35-ee95-597b-8fc3-d33ea6ab0660'::uuid, 'Qui Hippolyte aime-t-il ?', 'mcq', '["Aricie","Phèdre","Œnone","Personne"]'::jsonb, 0, 'Elle appartient à une famille ennemie de Thésée : cet amour est lui aussi interdit.', 5),
    ('25d97907-ab85-5a42-bec8-ad77fb4d25a5'::uuid, '9d6def35-ee95-597b-8fc3-d33ea6ab0660'::uuid, 'En quelle année la pièce est-elle créée ?', 'mcq', '["1677","1667","1637","1694"]'::jsonb, 0, 'C’est la dernière tragédie profane de Racine.', 6),
    ('e2db6646-5034-5b13-88ab-30bda56adb17'::uuid, '9d6def35-ee95-597b-8fc3-d33ea6ab0660'::uuid, 'Racine présente la passion comme un choix libre de Phèdre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est une maladie subie, imposée par les dieux et l’hérédité : culpabilité et innocence y sont inséparables.', 7),
    ('d2c1a527-8ea0-5ef8-8b6f-9d2679b6d37b'::uuid, '9d6def35-ee95-597b-8fc3-d33ea6ab0660'::uuid, 'Quelle forme prennent les grandes scènes de la pièce ?', 'mcq', '["Des aveux successifs","Des combats","Des monologues comiques","Des scènes de foule"]'::jsonb, 0, 'À Œnone, à Hippolyte, à Thésée : la pièce avance par la parole qui échappe.', 8),
    ('027ac8fc-33d1-523c-a5aa-783bd239bf4c'::uuid, 'a77f9ea5-0a79-575a-9e8b-4a0561a1c28d'::uuid, 'Qui Figaro veut-il épouser ?', 'mcq', '["Suzanne, camériste de la comtesse","Marceline","La comtesse Rosine","Fanchette"]'::jsonb, 0, 'Le comte veut faire valoir sur elle un droit qu’il avait pourtant aboli.', 1),
    ('ce04ad7a-7fa4-5b63-8cd1-80a3fb6e7da3'::uuid, 'a77f9ea5-0a79-575a-9e8b-4a0561a1c28d'::uuid, 'Que découvre-t-on au cours du procès burlesque ?', 'mcq', '["Marceline est la mère de Figaro","Figaro est le fils du comte","Suzanne est déjà mariée","Chérubin est un imposteur"]'::jsonb, 0, 'Le coup de théâtre transforme la créancière en mère.', 2),
    ('0109702d-f3d8-5fd9-9b90-0aed3f106ffd'::uuid, 'a77f9ea5-0a79-575a-9e8b-4a0561a1c28d'::uuid, 'Quel reproche Figaro adresse-t-il au comte dans son monologue ?', 'mcq', '["De s’être donné la peine de naître, et rien de plus","De ne pas savoir se battre","D’avoir ruiné le château","De ne pas aimer sa femme"]'::jsonb, 0, 'C’est l’un des textes politiques les plus célèbres du XVIIIe siècle.', 3),
    ('7fb25dd4-9d2a-5e1b-8d7a-53f5b0580b6d'::uuid, 'a77f9ea5-0a79-575a-9e8b-4a0561a1c28d'::uuid, 'Combien de temps dure l’action de la pièce ?', 'mcq', '["Une seule journée","Une semaine","Un mois","Trois jours"]'::jsonb, 0, 'D’où le titre : La Folle Journée.', 4),
    ('945936ef-38da-5843-a040-8865ea899650'::uuid, 'a77f9ea5-0a79-575a-9e8b-4a0561a1c28d'::uuid, 'Qui est Chérubin ?', 'mcq', '["Un jeune page amoureux de toutes les femmes du château","Le frère de Suzanne","Le juge du procès","Le jardinier"]'::jsonb, 0, 'Son personnage est un ressort comique constant et une provocation pour le comte.', 5),
    ('3be08a5f-5aef-554e-8bbe-254831aa64a4'::uuid, 'a77f9ea5-0a79-575a-9e8b-4a0561a1c28d'::uuid, 'En quelle année la pièce est-elle enfin créée ?', 'mcq', '["1784","1775","1789","1762"]'::jsonb, 0, 'Après trois ans d’interdiction par Louis XVI.', 6),
    ('d8148d5c-6c9c-517c-b287-59713fb6f15c'::uuid, 'a77f9ea5-0a79-575a-9e8b-4a0561a1c28d'::uuid, 'La pièce se contente de faire rire, sans portée politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Privilèges, censure, justice vénale, condition des femmes : elle attaque l’Ancien Régime cinq ans avant 1789.', 7),
    ('7416de43-05e2-5a74-89a9-269b968aa5dd'::uuid, 'a77f9ea5-0a79-575a-9e8b-4a0561a1c28d'::uuid, 'Comment se termine la pièce ?', 'mcq', '["Le comte, démasqué, demande pardon et le mariage a lieu","Le comte chasse Figaro","Suzanne épouse le comte","Figaro quitte le château"]'::jsonb, 0, 'La comtesse déguisée en Suzanne a piégé son mari dans le jardin.', 8),
    ('0facdd6e-15c9-5e08-b4d2-01cd35dfc47c'::uuid, '9a38c6e9-68db-560e-b81b-758b167053c7'::uuid, 'Quelle est la nouveauté du personnage de Figaro par rapport aux valets de Molière ?', 'mcq', '["Il devient le protagoniste, avec le titre et l’initiative","Il est plus comique","Il ne parle jamais de sa condition","Il est le confident du maître seulement"]'::jsonb, 0, 'Chez Molière, le valet sert la ruse d’un autre ; ici, il conduit la pièce.', 1),
    ('e2f64e8c-8941-5604-a2b6-378da167b8eb'::uuid, '9a38c6e9-68db-560e-b81b-758b167053c7'::uuid, 'Que raconte Figaro dans son monologue de l’acte V ?', 'mcq', '["Le bilan de sa vie et l’injustice de la naissance","Ses projets de mariage","La généalogie du comte","Un conte pour endormir Suzanne"]'::jsonb, 0, 'C’est le plus long monologue du théâtre français classique.', 2),
    ('3b0035d2-39df-5ae2-8ad1-70345b813a76'::uuid, '9a38c6e9-68db-560e-b81b-758b167053c7'::uuid, 'Qui organise le piège final dans le jardin ?', 'mcq', '["Suzanne et la comtesse","Figaro seul","Le comte","Chérubin"]'::jsonb, 0, 'Le renversement est social et féminin : ce sont les femmes qui gagnent.', 3),
    ('cba36416-7301-53c8-b591-13918256e30a'::uuid, '9a38c6e9-68db-560e-b81b-758b167053c7'::uuid, 'Quel personnage dénonce le sort fait aux femmes séduites puis abandonnées ?', 'mcq', '["Marceline","Suzanne","Fanchette","La comtesse"]'::jsonb, 0, 'Sa tirade est l’un des passages les plus audacieux de la pièce.', 4),
    ('60236aa5-b56c-5bd9-ae0b-b3b7aea1c432'::uuid, '9a38c6e9-68db-560e-b81b-758b167053c7'::uuid, 'Quels objets servent de ressorts comiques ?', 'mcq', '["Le ruban, l’épingle et le billet","Une épée et un bouclier","Un miroir et une bougie","Un livre et une clé"]'::jsonb, 0, 'Beaumarchais fait tourner des scènes entières autour de menus objets.', 5),
    ('eb56660a-0ce2-51e7-8c1e-dbf4ccb105d6'::uuid, '9a38c6e9-68db-560e-b81b-758b167053c7'::uuid, 'Quelle pièce de Marivaux annonce ce renversement maître-valet ?', 'mcq', '["L’Île des esclaves","Le Jeu de l’amour et du hasard","Les Fausses Confidences","La Double Inconstance"]'::jsonb, 0, 'Marivaux y inverse explicitement les conditions.', 6),
    ('56f6345f-e584-5b8b-8480-a7a4869f4513'::uuid, '9a38c6e9-68db-560e-b81b-758b167053c7'::uuid, 'À la fin de la pièce, Figaro cesse d’être au service du comte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se marie, mais reste valet : l’égalité est gagnée dans le rire, pas dans les faits.', 7),
    ('771fd84d-a598-5232-a693-6c0e58e43aad'::uuid, '9a38c6e9-68db-560e-b81b-758b167053c7'::uuid, 'Où se déroule l’acte V ?', 'mcq', '["Dans le jardin, la nuit","Dans la chambre de la comtesse","Au tribunal","Dans l’antichambre du comte"]'::jsonb, 0, 'L’obscurité rend possibles les échanges d’identité qui piègent le comte.', 8),
    ('3dc5d44b-7df5-551f-8ba5-6b2756eca86e'::uuid, '262f3b2f-cfda-5b80-aefc-20686677af73'::uuid, 'Dans quelle situation Winnie se trouve-t-elle à l’acte I ?', 'mcq', '["Enterrée jusqu’à la taille dans un mamelon de terre","Assise sur un banc","Enfermée dans une chambre","Debout sur une scène nue"]'::jsonb, 0, 'À l’acte II, elle est enterrée jusqu’au cou.', 1),
    ('1b3d9b26-6589-5387-acc0-23d725d81fc9'::uuid, '262f3b2f-cfda-5b80-aefc-20686677af73'::uuid, 'Qui est Willie ?', 'mcq', '["Le mari de Winnie, presque muet, qui rampe derrière le mamelon","Son fils","Un passant","Le narrateur de la pièce"]'::jsonb, 0, 'Il répond par monosyllabes, quand il répond.', 2),
    ('0292dc80-fa68-5342-b5c3-91ffca840215'::uuid, '262f3b2f-cfda-5b80-aefc-20686677af73'::uuid, 'Que fait Winnie pendant toute la pièce ?', 'mcq', '["Elle parle presque sans interruption","Elle tente de s’échapper","Elle dort","Elle écrit une lettre"]'::jsonb, 0, 'La parole est sa seule preuve d’existence.', 3),
    ('60bb3772-f905-599a-a182-265e3b367b21'::uuid, '262f3b2f-cfda-5b80-aefc-20686677af73'::uuid, 'Quelle phrase Winnie répète-t-elle ?', 'mcq', '["« Oh, le beau jour que ça aura été »","« Rien à faire »","« Demain sera meilleur »","« Je ne peux plus continuer »"]'::jsonb, 0, 'Prononcée depuis la terre qui l’engloutit, la formule est le cœur ironique du texte.', 4),
    ('0588800b-c5d1-5a85-bab4-f634c537a23e'::uuid, '262f3b2f-cfda-5b80-aefc-20686677af73'::uuid, 'Quel objet inquiétant se trouve dans le sac de Winnie ?', 'mcq', '["Un revolver","Un couteau","Une lettre d’adieu","Un miroir brisé"]'::jsonb, 0, 'Il reste là, jamais utilisé : la menace est permanente et sans effet.', 5),
    ('2784c3db-df76-5b9d-8a47-903bd945f984'::uuid, '262f3b2f-cfda-5b80-aefc-20686677af73'::uuid, 'Quel registre Beckett mêle-t-il au tragique de la situation ?', 'mcq', '["Le comique, hérité du burlesque","Le lyrisme romantique","Le registre épique","Le registre polémique"]'::jsonb, 0, 'Le spectateur rit d’une femme qui disparaît : c’est ce qui rend la pièce plus cruelle encore.', 6),
    ('4ca933db-a9c2-515d-b228-d9c61ee60c43'::uuid, '262f3b2f-cfda-5b80-aefc-20686677af73'::uuid, 'La pièce comporte une intrigue avec des rebondissements.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Rien n’arrive : la pièce est faite de rituels répétés et d’un enlisement.', 7),
    ('9451c371-356f-5100-807a-69d202c23d6d'::uuid, '262f3b2f-cfda-5b80-aefc-20686677af73'::uuid, 'Sous quel titre la pièce a-t-elle d’abord été créée ?', 'mcq', '["Happy Days, en anglais","Fin de partie","En attendant Godot","Not I"]'::jsonb, 0, 'Beckett écrivait dans les deux langues et traduisait lui-même ses pièces.', 8),
    ('39002db1-96ee-5d83-95f9-39baf13e8ee5'::uuid, 'dc404759-bf46-559e-aaeb-2abd73923ebc'::uuid, 'Que reste-t-il à Winnie à l’acte II ?', 'mcq', '["La parole et le souvenir","Ses objets","La possibilité de bouger","La compagnie de Willie"]'::jsonb, 0, 'Le corps disparaît, le langage continue : c’est le mouvement de la pièce.', 1),
    ('13cc214f-ee49-57ba-9c0d-4c85d8670031'::uuid, 'dc404759-bf46-559e-aaeb-2abd73923ebc'::uuid, 'Que retire Beckett au théâtre traditionnel ?', 'mcq', '["L’intrigue, la psychologie, l’espace vraisemblable et le temps","Seulement le décor","Uniquement les didascalies","Le dialogue"]'::jsonb, 0, 'Ce qui reste est une voix qui refuse de s’arrêter.', 2),
    ('37367d1b-02c3-5fb0-a97f-50bdb975d544'::uuid, 'dc404759-bf46-559e-aaeb-2abd73923ebc'::uuid, 'Comment interpréter l’optimisme répété de Winnie ?', 'mcq', '["Comme une stratégie de survie, ni naïve ni aveugle","Comme une ironie pure","Comme un signe de folie clinique","Comme une croyance religieuse"]'::jsonb, 0, 'La pièce refuse de trancher, et c’est ce qui la rend forte.', 3),
    ('76a985bf-89e0-5487-b96d-4404cf1375b9'::uuid, 'dc404759-bf46-559e-aaeb-2abd73923ebc'::uuid, 'Quelle particularité les didascalies de Beckett présentent-elles ?', 'mcq', '["Une précision extrême, jusqu’à la durée des pauses","Elles sont absentes","Elles sont écrites en vers","Elles laissent toute liberté au metteur en scène"]'::jsonb, 0, 'Le texte est aussi une partition de mise en scène.', 4),
    ('40f77222-f9ce-5b72-a6eb-1821d5d3f04b'::uuid, 'dc404759-bf46-559e-aaeb-2abd73923ebc'::uuid, 'Quel objet du quotidien accompagne les rituels de Winnie ?', 'mcq', '["Une brosse à dents dont l’inscription s’efface","Un chapelet","Une montre arrêtée","Un carnet"]'::jsonb, 0, 'Le détail minuscule porte le temps qui use tout.', 5),
    ('3c17020d-78ee-56e7-b9a6-89b10b0146b1'::uuid, 'dc404759-bf46-559e-aaeb-2abd73923ebc'::uuid, 'Que règle la sonnerie dans la pièce ?', 'mcq', '["Le réveil et le coucher, dans un jour qui recommence","Les entrées de Willie","Les changements d’acte","La fin de la représentation"]'::jsonb, 0, 'Elle remplace le temps par une contrainte mécanique.', 6),
    ('732e6a8f-8ea2-5fd8-89e9-3908023fbb28'::uuid, 'dc404759-bf46-559e-aaeb-2abd73923ebc'::uuid, 'Chez Beckett, le rire et le désespoir s’excluent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils sont indissociables : c’est le rire qui rend la cruauté supportable, et plus aiguë.', 7),
    ('3d06a47f-4955-5ca7-ad2d-56085c734af6'::uuid, 'dc404759-bf46-559e-aaeb-2abd73923ebc'::uuid, 'Que démontre la pièce sur ce qui définit l’humain ?', 'mcq', '["Il tient à ce qu’il peut encore dire, plus qu’à ce qu’il peut faire","Il tient à son travail","Il tient à sa mémoire familiale","Il tient à sa liberté de mouvement"]'::jsonb, 0, 'La voix, l’adresse à l’autre et le rituel sont ce qui subsiste.', 8),
    ('8401e936-8387-5357-90e5-ea3b1944dcae'::uuid, 'd7cc9da6-21a6-5261-b319-a23e24496a4d'::uuid, 'Que signifie le mot « essai » chez Montaigne ?', 'mcq', '["Une tentative, une mise à l’épreuve de la pensée","Un traité systématique","Une autobiographie complète","Un discours de circonstance"]'::jsonb, 0, '« Je ne peins pas l’être, je peins le passage. »', 1),
    ('92cd4a73-65d3-53b7-904b-7f42caa54dfe'::uuid, 'd7cc9da6-21a6-5261-b319-a23e24496a4d'::uuid, 'Quel peuple Montaigne a-t-il rencontré à Rouen ?', 'mcq', '["Des Tupinambas du Brésil","Des Aztèques du Mexique","Des Incas du Pérou","Des Iroquois du Canada"]'::jsonb, 0, 'Cette rencontre nourrit directement « Des Cannibales ».', 2),
    ('204c492c-78aa-5e8c-a5ef-397bd5e2ad53'::uuid, 'd7cc9da6-21a6-5261-b319-a23e24496a4d'::uuid, 'Quelle est la thèse célèbre de « Des Cannibales » ?', 'mcq', '["Chacun appelle barbarie ce qui n’est pas de son usage","Les cannibales sont des sauvages sans loi","La civilisation européenne est un modèle","Il faut convertir les peuples nouveaux"]'::jsonb, 0, 'Le mot « barbare » désigne le jugement de celui qui le prononce.', 3),
    ('cc848f06-6bd3-5011-92e7-2809a01fafd2'::uuid, 'd7cc9da6-21a6-5261-b319-a23e24496a4d'::uuid, 'Que dénonce Montaigne dans « Des Coches » ?', 'mcq', '["La destruction des civilisations du Nouveau Monde par la conquête","Le luxe des carrosses seulement","La faiblesse militaire de la France","Les guerres de religion en Allemagne"]'::jsonb, 0, '« Tant de villes rasées, tant de nations exterminées. »', 4),
    ('caf4ee13-3c85-5301-91e6-044c3c41dcf7'::uuid, 'd7cc9da6-21a6-5261-b319-a23e24496a4d'::uuid, 'Quel écart Montaigne souligne-t-il chez les conquérants ?', 'mcq', '["Une supériorité technique doublée d’une infériorité morale","Une supériorité militaire et morale","Une infériorité technique","Une égalité parfaite avec les Amérindiens"]'::jsonb, 0, 'La rencontre aurait pu être un échange ; elle a été un massacre.', 5),
    ('bfe9ecaa-a3f3-58fa-8202-17447f86071a'::uuid, 'd7cc9da6-21a6-5261-b319-a23e24496a4d'::uuid, 'À partir de quelle année les Essais paraissent-ils ?', 'mcq', '["1580","1532","1610","1550"]'::jsonb, 0, 'Montaigne les augmente ensuite jusqu’à sa mort en 1592.', 6),
    ('5d22b134-87a0-59a8-958f-44166cd0560a'::uuid, 'd7cc9da6-21a6-5261-b319-a23e24496a4d'::uuid, 'Montaigne écrit un traité systématique avec un plan rigoureux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il pense en avançant : digressions, contradictions et reprises font partie de la méthode.', 7),
    ('e5025d03-c5f3-5582-b6bf-3c82ae3d5991'::uuid, 'd7cc9da6-21a6-5261-b319-a23e24496a4d'::uuid, 'Quel usage Montaigne fait-il du « je » ?', 'mcq', '["Il s’examine lui-même pour examiner l’homme en général","Il raconte sa carrière politique","Il défend sa réputation","Il évite d’en parler"]'::jsonb, 0, 'Le sujet du livre, dit l’avis au lecteur, c’est lui-même — comme instrument de connaissance.', 8),
    ('ae93ba38-9423-546e-aace-e91bca49c0fb'::uuid, 'ca4d2c71-da6a-5f23-9c58-2ca097a48e80'::uuid, 'Quelle est la devise de Montaigne ?', 'mcq', '["« Que sais-je ? »","« Je pense donc je suis »","« Connais-toi toi-même »","« Rien de trop »"]'::jsonb, 0, 'Le doute y est une discipline de la pensée, non une paresse.', 1),
    ('b4cdeeab-0c87-5cd6-a771-5f38c0af5488'::uuid, 'ca4d2c71-da6a-5f23-9c58-2ca097a48e80'::uuid, 'Quel événement ébranle l’autorité des Anciens au XVIe siècle ?', 'mcq', '["La découverte d’un continent qu’aucun savoir n’avait prévu","L’invention de l’imprimerie","La chute de Constantinople","La Réforme protestante"]'::jsonb, 0, 'Si l’on a pu ignorer un monde entier, que valent nos autres certitudes ?', 2),
    ('2674a3bc-3ed7-5231-a988-22ea58ee4d33'::uuid, 'ca4d2c71-da6a-5f23-9c58-2ca097a48e80'::uuid, 'Le relativisme de Montaigne l’empêche-t-il de juger ?', 'mcq', '["Non : il condamne fermement la torture et la cruauté","Oui, il refuse tout jugement","Oui, il juge toutes les cultures équivalentes","Non, mais il ne juge que les peuples lointains"]'::jsonb, 0, 'Le relativisme est un instrument critique, pas une démission morale.', 3),
    ('6eac3b82-dd88-5dc7-bb11-e9dce773419f'::uuid, 'ca4d2c71-da6a-5f23-9c58-2ca097a48e80'::uuid, 'À quoi sert la description idéalisée des Tupinambas ?', 'mcq', '["À faire voir par contraste les vices de la société française","À encourager la colonisation","À prouver leur infériorité","À écrire un traité d’ethnographie"]'::jsonb, 0, 'C’est une utopie critique, un miroir tendu à l’Europe des guerres de religion.', 4),
    ('3855fee2-ea61-5d9c-ba6d-9a790bd9de2b'::uuid, 'ca4d2c71-da6a-5f23-9c58-2ca097a48e80'::uuid, 'Comment nomme-t-on les ajouts successifs de Montaigne à son texte ?', 'mcq', '["Les allongeails","Les gloses","Les scolies","Les apostilles"]'::jsonb, 0, 'Le livre grossit d’édition en édition : la forme dit la thèse.', 5),
    ('c306bf2f-94c2-5073-be01-c57d579dd382'::uuid, 'ca4d2c71-da6a-5f23-9c58-2ca097a48e80'::uuid, 'Quel contexte français éclaire les Essais ?', 'mcq', '["Les guerres de religion","La Fronde","La Révolution","La guerre de Cent Ans"]'::jsonb, 0, 'La violence intérieure du royaume rend la leçon de tolérance urgente.', 6),
    ('2d42fcef-4b44-5838-840a-6b79e667a847'::uuid, 'ca4d2c71-da6a-5f23-9c58-2ca097a48e80'::uuid, 'Montaigne conclut chacun de ses chapitres par une thèse ferme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le refus de conclure fait partie de sa méthode : une pensée honnête bouge.', 7),
    ('a4d3ba39-3043-5382-973a-4d7a4d0d0477'::uuid, 'ca4d2c71-da6a-5f23-9c58-2ca097a48e80'::uuid, 'Dans quel chapitre se trouve la formule « notre monde vient d’en trouver un autre » ?', 'mcq', '["Des Coches","Des Cannibales","De l’amitié","De l’institution des enfants"]'::jsonb, 0, 'Elle ouvre la réflexion sur la conquête du Nouveau Monde.', 8),
    ('01115360-9970-5de1-9cc4-a6ff2d5b2120'::uuid, '586037af-584a-54bd-8fef-a2b3455dc2e7'::uuid, 'Quels livres des Fables le programme retient-il ?', 'mcq', '["Les livres VII à XI","Les livres I à VI","Le livre XII seul","Tous les livres"]'::jsonb, 0, 'Le second recueil, plus sombre et plus philosophique que le premier.', 1),
    ('9bfa3693-19bf-5eca-b977-aa3e04896eee'::uuid, '586037af-584a-54bd-8fef-a2b3455dc2e7'::uuid, 'Quel principe La Fontaine formule-t-il sur la morale ?', 'mcq', '["« Une morale nue apporte de l’ennui : le conte fait passer le précepte avec lui »","« Il faut instruire avant de plaire »","« La fable doit être vraie »","« Le rire corrige les mœurs »"]'::jsonb, 0, 'Plaire est la condition de l’instruction, pas son contraire.', 2),
    ('dac67635-f4e9-56c9-bbef-9c56b8514dbc'::uuid, '586037af-584a-54bd-8fef-a2b3455dc2e7'::uuid, 'Quelle fable contient le vers « Selon que vous serez puissant ou misérable… » ?', 'mcq', '["Les Animaux malades de la peste","Le Coche et la Mouche","Les Deux Pigeons","La Laitière et le Pot au lait"]'::jsonb, 0, 'Le plus faible, l’âne, est condamné pour la faute la plus légère.', 3),
    ('657b09af-36ba-5320-972b-41abbe0dc39d'::uuid, '586037af-584a-54bd-8fef-a2b3455dc2e7'::uuid, 'Quelle forme métrique La Fontaine emploie-t-il ?', 'mcq', '["Le vers libre, alternant notamment alexandrins et octosyllabes","L’alexandrin exclusivement","La prose","Le sonnet"]'::jsonb, 0, 'Le changement de mètre épouse le rythme du récit et souligne les chutes.', 4),
    ('5acd4bd1-705a-5fae-9197-13ff82755d47'::uuid, '586037af-584a-54bd-8fef-a2b3455dc2e7'::uuid, 'À quels auteurs antiques La Fontaine emprunte-t-il ses sujets ?', 'mcq', '["Ésope et Phèdre","Homère et Virgile","Sénèque et Cicéron","Ovide et Horace"]'::jsonb, 0, 'Il en transforme la matière par le style et l’humour.', 5),
    ('2afd3071-f883-5d01-9e78-ef174d4b9773'::uuid, '586037af-584a-54bd-8fef-a2b3455dc2e7'::uuid, 'Quel animal représente le roi dans les fables de cour ?', 'mcq', '["Le lion","Le renard","Le loup","L’aigle"]'::jsonb, 0, 'La cour y est peinte comme un théâtre d’hypocrisie.', 6),
    ('532d71a4-b4b1-5ec3-860c-e4611b4db889'::uuid, '586037af-584a-54bd-8fef-a2b3455dc2e7'::uuid, 'La morale est toujours explicite dans les Fables.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est parfois absente, ironique ou contredite par le récit : le lecteur doit conclure.', 7),
    ('e4856a61-f242-5027-b045-7c4f7ddc269c'::uuid, '586037af-584a-54bd-8fef-a2b3455dc2e7'::uuid, 'En quelle année paraît le second recueil des Fables ?', 'mcq', '["1678","1668","1694","1660"]'::jsonb, 0, 'Le premier recueil, livres I à VI, datait de 1668.', 8),
    ('0e0dcd1a-ca0f-53c9-94dd-af7c5f1c5f01'::uuid, '0a4c9175-4a6b-5c9c-83db-1d5b74948a9e'::uuid, 'Qui sont Usbek et Rica ?', 'mcq', '["Deux Persans qui voyagent en Europe et écrivent des lettres","Deux philosophes français","Deux marchands vénitiens","Deux frères espagnols"]'::jsonb, 0, 'Rica est moqueur, Usbek grave : deux tons pour deux fonctions.', 1),
    ('40b793bc-d5b8-515f-8ecb-bc47339ed75e'::uuid, '0a4c9175-4a6b-5c9c-83db-1d5b74948a9e'::uuid, 'Quelle célèbre exclamation Rica rapporte-t-il ?', 'mcq', '["« Comment peut-on être Persan ? »","« Que sais-je ? »","« Il faut cultiver notre jardin »","« Écrasons l’infâme »"]'::jsonb, 0, 'L’étranger devient une curiosité : la scène retourne le regard sur les Parisiens.', 2),
    ('4913ce7f-260c-5108-8bb2-30d4532ffb2e'::uuid, '0a4c9175-4a6b-5c9c-83db-1d5b74948a9e'::uuid, 'Comment Rica décrit-il le roi de France ?', 'mcq', '["Comme un grand magicien qui fait croire que le papier est de l’argent","Comme un tyran sanguinaire","Comme un sage philosophe","Comme un général invincible"]'::jsonb, 0, 'Le pape est décrit comme un autre magicien : la naïveté feinte démasque la croyance.', 3),
    ('4f6d7822-56a5-5dbf-9fdf-fb1a63250319'::uuid, '0a4c9175-4a6b-5c9c-83db-1d5b74948a9e'::uuid, 'Que révèle la dernière lettre du roman ?', 'mcq', '["Roxane a trahi Usbek, s’est empoisonnée et ne l’a jamais aimé","Usbek rentre en Perse","Rica se marie à Paris","Le sérail est détruit par un incendie"]'::jsonb, 0, 'Le penseur de la liberté était un despote chez lui : la leçon est cinglante.', 4),
    ('ebb19615-6d5e-5a02-8013-679f6853b5eb'::uuid, '0a4c9175-4a6b-5c9c-83db-1d5b74948a9e'::uuid, 'Combien de lettres compte le roman ?', 'mcq', '["161","50","300","99"]'::jsonb, 0, 'Elles sont écrites par une quinzaine de correspondants différents.', 5),
    ('3b9ccac7-4992-5cd0-973f-9e79e0fe3a47'::uuid, '0a4c9175-4a6b-5c9c-83db-1d5b74948a9e'::uuid, 'En quelle année paraissent les Lettres persanes ?', 'mcq', '["1721","1748","1687","1759"]'::jsonb, 0, 'Publication anonyme à Amsterdam, pour échapper à la censure.', 6),
    ('3ab62aa6-9cfa-5e3c-8194-db4c29658006'::uuid, '0a4c9175-4a6b-5c9c-83db-1d5b74948a9e'::uuid, 'Le roman se limite à la satire amusante de la société française.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’intrigue du sérail lui donne une dimension tragique et politique.', 7),
    ('5b593857-421f-5a71-a9c5-8cfc2e547b85'::uuid, '0a4c9175-4a6b-5c9c-83db-1d5b74948a9e'::uuid, 'Quelle période historique les Persans découvrent-ils à Paris ?', 'mcq', '["La fin du règne de Louis XIV puis la Régence","Le règne de Louis XVI","La Révolution","Le règne de Henri IV"]'::jsonb, 0, 'Le contexte explique les pages sur la crise financière et le système de Law.', 8),
    ('0968e0fd-4f29-50f2-91ff-d393a59bcd4d'::uuid, '591a7cb6-1cda-5718-b14c-06d3464525e6'::uuid, 'Pourquoi Montesquieu choisit-il la fiction du regard étranger ?', 'mcq', '["Pour échapper à la censure, dépayser le lecteur et faire rire","Parce qu’il a voyagé en Perse","Pour imiter les contes orientaux à la mode uniquement","Pour écrire un traité de géographie"]'::jsonb, 0, 'Ce dont on rit cesse d’être sacré : le détour est une stratégie.', 1),
    ('e42eefbb-354c-5264-ba0e-cc945b25a0e8'::uuid, '591a7cb6-1cda-5718-b14c-06d3464525e6'::uuid, 'Que raconte l’apologue des Troglodytes ?', 'mcq', '["Un peuple égoïste s’autodétruit, une communauté vertueuse prospère puis réclame un roi","Une guerre entre la Perse et la France","La fondation d’Ispahan","Le naufrage d’Usbek"]'::jsonb, 0, 'C’est un conte politique inséré, qui annonce De l’esprit des lois.', 2),
    ('a1c95170-9cd3-5d94-8961-4a2eeb57bbf8'::uuid, '591a7cb6-1cda-5718-b14c-06d3464525e6'::uuid, 'Quel ouvrage majeur Montesquieu publiera-t-il en 1748 ?', 'mcq', '["De l’esprit des lois","Le Contrat social","L’Encyclopédie","Le Dictionnaire philosophique"]'::jsonb, 0, 'Il y systématise la question des institutions et de la liberté.', 3),
    ('9f9f804d-de36-508e-b926-689a0dccc2c3'::uuid, '591a7cb6-1cda-5718-b14c-06d3464525e6'::uuid, 'Que représente le sérail dans l’économie du roman ?', 'mcq', '["Un modèle réduit du pouvoir despotique","Un simple décor exotique","Une utopie","Un souvenir d’enfance d’Usbek"]'::jsonb, 0, 'Surveillance, peur, punitions, puis effondrement : le despotisme sans lois ne tient pas.', 4),
    ('0a2367d1-9b70-5f8a-ad55-4d50b8dcb625'::uuid, '591a7cb6-1cda-5718-b14c-06d3464525e6'::uuid, 'Quelle contradiction rend Usbek passionnant ?', 'mcq', '["Il dénonce le despotisme tout en l’exerçant chez lui","Il ment sur son origine","Il refuse de rentrer en Perse","Il ne croit pas ce qu’il écrit"]'::jsonb, 0, 'C’est la trouvaille du livre, et le sujet de dissertation le plus fréquent.', 5),
    ('cde3a005-6881-56f4-ac6d-985b794e2831'::uuid, '591a7cb6-1cda-5718-b14c-06d3464525e6'::uuid, 'Quelles institutions le roman vise-t-il principalement ?', 'mcq', '["La monarchie absolue, l’Église et la justice","L’armée et la marine","Les universités seules","Les corporations de métiers"]'::jsonb, 0, 'S’y ajoutent la mode, l’économie et le fanatisme.', 6),
    ('d7752078-f0cb-57fc-bf15-f08eab21e4c4'::uuid, '591a7cb6-1cda-5718-b14c-06d3464525e6'::uuid, 'Le regard de l’étranger est présenté comme parfaitement neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Usbek juge, se trompe et se contredit : il est lui-même objet du regard critique.', 7),
    ('5eaa3a2b-f3cb-55c8-a4ab-05327ce1330b'::uuid, '591a7cb6-1cda-5718-b14c-06d3464525e6'::uuid, 'Dans quelles lettres se trouve l’apologue des Troglodytes ?', 'mcq', '["Les lettres XI à XIV","Les lettres I à III","Les dernières lettres","La lettre unique de Roxane"]'::jsonb, 0, 'Elles forment un récit inséré au début du recueil.', 8),
    ('385bce8b-c478-5e2b-b0ce-48a17dd84be6'::uuid, 'e24aec34-2fad-5a75-bc7e-d0c6a2e7283a'::uuid, 'En quelle année et comment le roman paraît-il ?', 'mcq', '["En 1678, de façon anonyme","En 1678, signé par son autrice","En 1731, anonyme","En 1700, signé"]'::jsonb, 0, 'L’anonymat protégeait une femme de lettres et alimentait la curiosité.', 1),
    ('ce426ea3-0181-5022-af60-161aa0359131'::uuid, 'e24aec34-2fad-5a75-bc7e-d0c6a2e7283a'::uuid, 'À quelle époque se déroule l’action ?', 'mcq', '["À la cour de Henri II, en 1558-1559","Sous Louis XIV","Pendant la Fronde","Sous François Ier"]'::jsonb, 0, 'La reconstitution historique est précise : la cour y fonctionne comme un système de surveillance.', 2),
    ('b728927e-0afe-5605-87ac-ad0c3c70d6f5'::uuid, 'e24aec34-2fad-5a75-bc7e-d0c6a2e7283a'::uuid, 'Qu’est-ce que la scène de l’aveu ?', 'mcq', '["La princesse avoue à son mari qu’elle aime un autre homme","Nemours déclare son amour au roi","La mère de la princesse avoue une faute","Le prince avoue une infidélité"]'::jsonb, 0, 'Nemours, caché, entend tout : c’est le nœud du roman.', 3),
    ('b93c6ba3-ed32-5990-8f6b-ad8bec388b49'::uuid, 'e24aec34-2fad-5a75-bc7e-d0c6a2e7283a'::uuid, 'De quoi meurt le prince de Clèves ?', 'mcq', '["De jalousie et de chagrin","Dans un tournoi","Assassiné","D’une épidémie"]'::jsonb, 0, 'Il meurt persuadé que sa femme s’est donnée à Nemours.', 4),
    ('74b99b0f-4b39-502e-bafd-15c6f2065c78'::uuid, 'e24aec34-2fad-5a75-bc7e-d0c6a2e7283a'::uuid, 'Que décide la princesse à la fin du roman ?', 'mcq', '["Elle refuse d’épouser Nemours et se retire","Elle épouse Nemours","Elle entre définitivement au couvent dès la mort de son mari","Elle quitte la France"]'::jsonb, 0, 'Devoir envers le mort, mais aussi certitude que la passion ne durerait pas.', 5),
    ('1bfda3cc-d1ed-5fb5-b71c-e284b6392a30'::uuid, 'e24aec34-2fad-5a75-bc7e-d0c6a2e7283a'::uuid, 'Qu’est-ce qui fait la nouveauté du roman ?', 'mcq', '["L’analyse des mouvements intérieurs plutôt que l’action extérieure","Le récit à la première personne","Le mélange des genres","La longueur des descriptions"]'::jsonb, 0, 'C’est pour cela qu’on parle du premier roman d’analyse.', 6),
    ('d6107837-5af5-5441-8068-9b67ae35fcc4'::uuid, 'e24aec34-2fad-5a75-bc7e-d0c6a2e7283a'::uuid, 'Le refus final de la princesse est unanimement interprété comme de la vertu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Orgueil, sagesse, peur ou liberté : le texte laisse les lectures ouvertes.', 7),
    ('15c1d52a-4537-54a0-afa0-636b917718de'::uuid, 'e24aec34-2fad-5a75-bc7e-d0c6a2e7283a'::uuid, 'Quel personnage met la princesse en garde contre la passion ?', 'mcq', '["Sa mère, Madame de Chartres","Le roi","La reine dauphine","Le vidame de Chartres"]'::jsonb, 0, 'Son avertissement, prononcé sur son lit de mort, pèse sur tout le roman.', 8),
    ('d6e3836d-e613-58ec-b717-b229dcb0cac6'::uuid, 'c4dfe87c-0fd1-5e47-b13f-cc25aa2de2e6'::uuid, 'Que désignent le rouge et le noir du titre ?', 'mcq', '["L’armée et l’Église, les deux voies d’ascension possibles","La passion et la mort","La révolution et la monarchie","Le sang et l’encre"]'::jsonb, 0, 'Julien aurait été officier sous Napoléon ; sous la Restauration, il ne reste que la soutane.', 1),
    ('9333b3bf-5283-5cff-b89f-82d78ed3e21f'::uuid, 'c4dfe87c-0fd1-5e47-b13f-cc25aa2de2e6'::uuid, 'Quelle est l’origine sociale de Julien Sorel ?', 'mcq', '["Fils d’un charpentier de Verrières","Fils d’un notaire de Besançon","Orphelin recueilli par l’Église","Fils d’un officier de l’Empire"]'::jsonb, 0, 'Son origine explique l’orgueil de classe qui gouverne toutes ses conduites.', 2),
    ('f3e367b7-8da4-55dd-be42-a44bcb16fb0c'::uuid, 'c4dfe87c-0fd1-5e47-b13f-cc25aa2de2e6'::uuid, 'Quel livre nourrit l’imagination de Julien ?', 'mcq', '["Le Mémorial de Sainte-Hélène","Les Confessions de Rousseau","L’Encyclopédie","Les Fables de La Fontaine"]'::jsonb, 0, 'Napoléon est son modèle secret, dans une France qui l’a renié.', 3),
    ('45a53530-84f5-59f7-aafe-575fe0ff5f46'::uuid, 'c4dfe87c-0fd1-5e47-b13f-cc25aa2de2e6'::uuid, 'Que provoque la lettre de Madame de Rênal ?', 'mcq', '["La ruine du mariage prévu avec Mathilde et le geste criminel de Julien","L’arrestation du marquis","Le départ de Julien pour l’armée","La conversion de Julien"]'::jsonb, 0, 'Dictée par son confesseur, elle dénonce Julien comme un séducteur ambitieux.', 4),
    ('52110090-cb9e-5b9e-9f51-c540a32a09fe'::uuid, 'c4dfe87c-0fd1-5e47-b13f-cc25aa2de2e6'::uuid, 'Où Julien tire-t-il sur Madame de Rênal ?', 'mcq', '["Dans l’église de Verrières, pendant la messe","Dans le jardin des Rênal","À Paris, chez les La Mole","Au séminaire de Besançon"]'::jsonb, 0, 'Le lieu et le moment donnent au geste sa portée de scandale.', 5),
    ('c17d28ae-a396-5f3b-a4bd-2cf8342a989f'::uuid, 'c4dfe87c-0fd1-5e47-b13f-cc25aa2de2e6'::uuid, 'Que fait Julien lors de son procès ?', 'mcq', '["Il accuse la société de le condamner comme paysan sorti de sa classe","Il plaide la folie","Il nie les faits","Il demande la clémence du jury"]'::jsonb, 0, 'Il refuse de se défendre : le discours de tribunal est le sommet politique du roman.', 6),
    ('1ec0035d-22cd-58a7-8dcc-2bf0cdc45f09'::uuid, 'c4dfe87c-0fd1-5e47-b13f-cc25aa2de2e6'::uuid, 'Mathilde de La Mole et Madame de Rênal aiment Julien de la même façon.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’une l’aime par orgueil et romanesque, l’autre par tendresse : le roman oppose deux amours.', 7),
    ('f5635d3c-dd3f-5998-91f8-d34d2f73adc8'::uuid, 'c4dfe87c-0fd1-5e47-b13f-cc25aa2de2e6'::uuid, 'Quelle définition du roman Stendhal donne-t-il ?', 'mcq', '["« Un miroir que l’on promène le long d’un chemin »","« Une machine à explorer le temps »","« Une tranche de vie »","« Un art de la mémoire »"]'::jsonb, 0, 'Elle justifie le sous-titre : Chronique de 1830.', 8),
    ('05ef77e9-3e90-5006-933b-6554b9a9b0b4'::uuid, '67b7d818-4306-5189-b3cd-38d837ad1709'::uuid, 'Comment le roman construit-il le personnage de Julien ?', 'mcq', '["Comme un être ambivalent, dont on épouse le point de vue sans l’approuver","Comme un héros exemplaire","Comme un pur criminel","Comme un narrateur ironique"]'::jsonb, 0, 'Ce refus de trancher est une révolution esthétique.', 1),
    ('1dde7cb5-468e-551e-9fa8-5af194854551'::uuid, '67b7d818-4306-5189-b3cd-38d837ad1709'::uuid, 'Quel procédé fait entendre la pensée du personnage à l’intérieur du récit ?', 'mcq', '["Le discours indirect libre","L’aparté","La didascalie","Le monologue intérieur non ponctué"]'::jsonb, 0, 'Il permet de suivre les calculs de Julien sans les endosser.', 2),
    ('29b8d640-dbab-550a-b83b-c80095e24aef'::uuid, '67b7d818-4306-5189-b3cd-38d837ad1709'::uuid, 'Quelle période politique le roman peint-il ?', 'mcq', '["La Restauration finissante, en 1830","Le Premier Empire","La Révolution de 1789","Le Second Empire"]'::jsonb, 0, 'Une société bloquée, où l’énergie individuelle n’a plus d’issue légitime.', 3),
    ('b3064889-fd01-5456-b1a1-c3010d4d67c8'::uuid, '67b7d818-4306-5189-b3cd-38d837ad1709'::uuid, 'Quel rôle joue l’ironie du narrateur ?', 'mcq', '["Elle permet la satire et la distance critique","Elle rend le récit comique","Elle masque les intentions de l’auteur","Elle ralentit le récit"]'::jsonb, 0, 'Le narrateur dit souvent le contraire de ce qu’il montre.', 4),
    ('a333cfff-85c2-5251-a2f8-bb75b1d08ef1'::uuid, '67b7d818-4306-5189-b3cd-38d837ad1709'::uuid, 'Quel modèle stylistique Stendhal revendiquait-il ?', 'mcq', '["Le Code civil, contre le lyrisme","La poésie de Lamartine","Les sermons de Bossuet","Les romans de Walter Scott"]'::jsonb, 0, 'D’où la phrase sèche et rapide, sans « beau style ».', 5),
    ('17338bd2-ef00-5a06-8582-cec229312544'::uuid, '67b7d818-4306-5189-b3cd-38d837ad1709'::uuid, 'Que révèle le crime de Julien selon la lecture sociale du roman ?', 'mcq', '["Le geste d’un homme à qui l’on retire la place qu’il avait arrachée","Une simple crise de jalousie","Un accident","Une manœuvre politique"]'::jsonb, 0, 'Le procès le dit explicitement : c’est un paysan qu’on condamne.', 6),
    ('17ee2629-258d-5ed8-b9b7-a20ad2d83d06'::uuid, '67b7d818-4306-5189-b3cd-38d837ad1709'::uuid, 'Un personnage de roman doit être moralement exemplaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Julien démontre l’inverse : le roman peut faire aimer un personnage sans l’approuver.', 7),
    ('8bc58735-e04f-56b3-89de-db59b0f232d0'::uuid, '67b7d818-4306-5189-b3cd-38d837ad1709'::uuid, 'Quel personnage incarne l’amour par orgueil et par romanesque ?', 'mcq', '["Mathilde de La Mole","Madame de Rênal","Élisa","Madame Derville"]'::jsonb, 0, 'Elle rejoue la légende de Boniface de La Mole en ensevelissant la tête de Julien.', 8),
    ('86a9e69d-295f-572e-bb35-670e90a1e708'::uuid, 'ec9df03c-41c2-5f08-9441-cc8d9184c1b0'::uuid, 'Quelle est la forme du livre ?', 'mcq', '["Une longue lettre d’Hadrien à Marc Aurèle","Un journal intime tenu au jour le jour","Un dialogue entre deux empereurs","Un récit à la troisième personne"]'::jsonb, 0, 'Le récit est rétrospectif : un mourant reprend sa vie.', 1),
    ('05409d46-2857-5176-b43a-b8476857b369'::uuid, 'ec9df03c-41c2-5f08-9441-cc8d9184c1b0'::uuid, 'Qui est Antinoüs ?', 'mcq', '["Le jeune homme aimé d’Hadrien, noyé dans le Nil","Le père adoptif d’Hadrien","Le général de ses armées","Son médecin"]'::jsonb, 0, 'Hadrien le divinise et fonde une ville en son nom ; il ne s’en console pas.', 2),
    ('e4b15510-9b52-5809-aece-51fdf3fdb968'::uuid, 'ec9df03c-41c2-5f08-9441-cc8d9184c1b0'::uuid, 'Quels sont les premiers mots du livre ?', 'mcq', '["Animula vagula blandula","Alea jacta est","Ave Caesar","Carpe diem"]'::jsonb, 0, '« Petite âme vagabonde et charmante » : ce sont les mots du poème d’Hadrien mourant.', 3),
    ('2ae3af28-38f7-5ff9-a5a2-32c788ee7c37'::uuid, 'ec9df03c-41c2-5f08-9441-cc8d9184c1b0'::uuid, 'Quelle politique impériale Hadrien mène-t-il ?', 'mcq', '["Il arrête l’expansion et consolide les frontières","Il conquiert la Germanie","Il abandonne la Bretagne","Il déplace la capitale à Athènes"]'::jsonb, 0, 'Le mur de Bretagne en est le symbole le plus visible.', 4),
    ('e3d0cc65-76db-547e-847f-5119066622fa'::uuid, 'ec9df03c-41c2-5f08-9441-cc8d9184c1b0'::uuid, 'En quelle année le roman a-t-il été publié ?', 'mcq', '["1951","1938","1968","1980"]'::jsonb, 0, 'Yourcenar y a travaillé pendant près de trente ans.', 5),
    ('65d693bb-88a3-5a50-bedf-24fd39dd9b1e'::uuid, 'ec9df03c-41c2-5f08-9441-cc8d9184c1b0'::uuid, 'Comment Yourcenar résume-t-elle sa méthode ?', 'mcq', '["« Un pied dans l’érudition, l’autre dans la magie »","« Le roman est un miroir »","« Je peins le passage »","« Écrire, c’est se souvenir »"]'::jsonb, 0, 'La formule figure dans les Carnets de notes qui accompagnent le roman.', 6),
    ('0fde4f72-c8de-5047-9bae-69ef33a94c98'::uuid, 'ec9df03c-41c2-5f08-9441-cc8d9184c1b0'::uuid, 'Le livre est une biographie savante sans part de fiction.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un roman : il reconstruit de l’intérieur une conscience, à partir de sources réelles.', 7),
    ('0a390d22-6a91-58b4-ae95-74e131f0ad47'::uuid, 'ec9df03c-41c2-5f08-9441-cc8d9184c1b0'::uuid, 'À qui Hadrien adresse-t-il son récit ?', 'mcq', '["À Marc Aurèle, son petit-fils adoptif","À Trajan","Au Sénat de Rome","À Antinoüs"]'::jsonb, 0, 'L’adresse à un successeur adolescent donne au livre sa tonalité de transmission.', 8),
    ('da659a42-9b28-598d-b803-01b274f498f6'::uuid, '7b8b6970-b91a-5e3b-aaab-7f56bb0d89ff'::uuid, 'Quelle maison d’édition est associée au Nouveau Roman ?', 'mcq', '["Les Éditions de Minuit","Gallimard","Le Seuil","Flammarion"]'::jsonb, 0, 'Jérôme Lindon y publie Robbe-Grillet, Simon, Pinget, Duras.', 1),
    ('d3c40821-329a-5032-b45f-fdfb685ffc46'::uuid, '7b8b6970-b91a-5e3b-aaab-7f56bb0d89ff'::uuid, 'Qui a écrit L’Ère du soupçon ?', 'mcq', '["Nathalie Sarraute","Alain Robbe-Grillet","Michel Butor","Claude Simon"]'::jsonb, 0, 'Publié en 1956, l’essai annonce la fin de la croyance au personnage.', 2),
    ('b85146bc-f69b-5cc4-93e2-be5abb121e3e'::uuid, '7b8b6970-b91a-5e3b-aaab-7f56bb0d89ff'::uuid, 'Quel manifeste Robbe-Grillet publie-t-il en 1963 ?', 'mcq', '["Pour un nouveau roman","Le Degré zéro de l’écriture","Qu’est-ce que la littérature ?","L’Ère du soupçon"]'::jsonb, 0, 'Il y théorise le refus du personnage, de l’intrigue et de la métaphore.', 3),
    ('27de4abe-0c89-575f-bd27-e4fb562290a6'::uuid, '7b8b6970-b91a-5e3b-aaab-7f56bb0d89ff'::uuid, 'Pourquoi parle-t-on d’« école du regard » ?', 'mcq', '["Parce que la description des objets remplace la psychologie","Parce que les auteurs écrivent sur la peinture","Parce que les récits sont vus par un narrateur unique","Parce que le cinéma les inspire seul"]'::jsonb, 0, 'Chez Robbe-Grillet, un objet est décrit géométriquement, sans métaphore.', 4),
    ('b1fa05c1-8e3c-5df6-b3b3-65d3bca9fad7'::uuid, '7b8b6970-b91a-5e3b-aaab-7f56bb0d89ff'::uuid, 'Quelle particularité présente La Modification de Butor ?', 'mcq', '["Le récit est écrit à la deuxième personne du pluriel","Il n’a pas de ponctuation","Il est écrit en vers","Il ne comporte aucun dialogue"]'::jsonb, 0, 'Le « vous » installe le lecteur dans la place du personnage.', 5),
    ('470de6d3-7cb8-5223-93d1-5c986aa4e45a'::uuid, '7b8b6970-b91a-5e3b-aaab-7f56bb0d89ff'::uuid, 'Que devient le rôle du lecteur dans le Nouveau Roman ?', 'mcq', '["Il doit reconstituer et accepter de ne pas tout savoir","Il est guidé pas à pas","Il est absent du dispositif","Il choisit la fin du récit"]'::jsonb, 0, 'Le récit ne conclut pas à sa place.', 6),
    ('d5ce88fd-5dbb-500c-a883-0a0f807c0c0c'::uuid, '7b8b6970-b91a-5e3b-aaab-7f56bb0d89ff'::uuid, 'Le Nouveau Roman forme une école organisée avec un chef et un programme commun.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un air de famille et un ensemble de refus, pas une école constituée.', 7),
    ('f35963d3-25cb-56da-8628-9b87fd4558a2'::uuid, '7b8b6970-b91a-5e3b-aaab-7f56bb0d89ff'::uuid, 'Quelle période correspond au Nouveau Roman ?', 'mcq', '["Les années 1950 à 1970","L’entre-deux-guerres","Les années 1980-1990","La fin du XIXe siècle"]'::jsonb, 0, 'Claude Simon recevra le prix Nobel de littérature en 1985.', 8),
    ('d3a39c35-c52e-5054-af44-af7e5c95b538'::uuid, '26a5ef96-f662-5094-ae45-e682d6b19596'::uuid, 'Comment le recueil est-il organisé ?', 'mcq', '["En deux ensembles, Autrefois et Aujourd’hui, séparés par la mort de Léopoldine","En quatre saisons","Par ordre chronologique de composition","En trois parties égales"]'::jsonb, 0, 'Six livres au total ; le programme retient les quatre premiers.', 1),
    ('441b1736-b150-52fa-9e76-606ffd6ed3db'::uuid, '26a5ef96-f662-5094-ae45-e682d6b19596'::uuid, 'Qui était Léopoldine ?', 'mcq', '["La fille aînée de Hugo, noyée à Villequier en 1843","Sa mère","Sa femme","Sa sœur"]'::jsonb, 0, 'Elle avait dix-neuf ans et venait de se marier.', 2),
    ('4e3f40e3-8865-581b-bfd9-517abd677e99'::uuid, '26a5ef96-f662-5094-ae45-e682d6b19596'::uuid, 'Quelle formule de la préface donne la clé du recueil ?', 'mcq', '["« Quand je vous parle de moi, je vous parle de vous »","« Je est un autre »","« Le poète est un phare »","« Il faut être absolument moderne »"]'::jsonb, 0, 'Le « je » lyrique est offert au lecteur comme un miroir.', 3),
    ('c2a34a5c-091d-5970-abd7-9d4f02c4480b'::uuid, '26a5ef96-f662-5094-ae45-e682d6b19596'::uuid, 'Quel poème célèbre ouvre le deuil de Pauca meae ?', 'mcq', '["« Demain, dès l’aube… »","« Melancholia »","« Réponse à un acte d’accusation »","« Vieille chanson du jeune temps »"]'::jsonb, 0, 'Le poème ne dit qu’à la fin qu’il s’agit d’une visite à une tombe.', 4),
    ('46065a6b-d937-5b89-a950-2f1d9acc5d31'::uuid, '26a5ef96-f662-5094-ae45-e682d6b19596'::uuid, 'Que raconte « Réponse à un acte d’accusation » ?', 'mcq', '["La révolution romantique du vocabulaire poétique","La mort de Léopoldine","L’exil à Guernesey","Un procès politique"]'::jsonb, 0, '« Je mis un bonnet rouge au vieux dictionnaire. »', 5),
    ('df17fc71-d2e2-5ad8-ab8b-4f94ff6b0c59'::uuid, '26a5ef96-f662-5094-ae45-e682d6b19596'::uuid, 'Quel thème domine le livre III, Les Luttes et les Rêves ?', 'mcq', '["La misère et l’injustice sociale","L’amour heureux","L’enfance à la campagne","La foi religieuse"]'::jsonb, 0, 'Hugo y est déjà le poète social des Misérables.', 6),
    ('6817b2b3-b423-55ca-bf9e-75456b1016b7'::uuid, '26a5ef96-f662-5094-ae45-e682d6b19596'::uuid, 'Les Contemplations sont une autobiographie de faits.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le récit d’une vie intérieure : « les Mémoires d’une âme ».', 7),
    ('d650d57a-c51a-5d29-af4b-4689bef8fdd9'::uuid, '26a5ef96-f662-5094-ae45-e682d6b19596'::uuid, 'Où Hugo se trouve-t-il lorsqu’il publie le recueil ?', 'mcq', '["En exil à Guernesey","À Paris","En Belgique","En Italie"]'::jsonb, 0, 'L’exil, commencé après le coup d’État de 1851, donne au livre sa position de retrait.', 8),
    ('d7c90bb4-12a8-560a-9fea-ac1c63252ccb'::uuid, '96deacc6-a828-5a10-a860-d3c1dc0cf8ba'::uuid, 'Que se passe-t-il lors de la publication du recueil en 1857 ?', 'mcq', '["Il est condamné et six pièces sont retranchées","Il obtient un prix littéraire","Il passe inaperçu","Il est interdit en totalité"]'::jsonb, 0, 'Une seconde édition augmentée paraît en 1861.', 1),
    ('1aceb6eb-7238-5d8f-9729-4c65ebbdb8d6'::uuid, '96deacc6-a828-5a10-a860-d3c1dc0cf8ba'::uuid, 'Quelle section a été ajoutée en 1861 ?', 'mcq', '["Tableaux parisiens","Spleen et Idéal","La Mort","Le Vin"]'::jsonb, 0, 'Elle fait entrer la ville moderne dans le recueil.', 2),
    ('ecfbebd2-d560-5221-93c8-4f90454c8881'::uuid, '96deacc6-a828-5a10-a860-d3c1dc0cf8ba'::uuid, 'Qu’est-ce que le spleen chez Baudelaire ?', 'mcq', '["Une angoisse sans objet, un ennui métaphysique","La nostalgie de l’enfance","La colère politique","Le désir de voyage"]'::jsonb, 0, '« Quand le ciel bas et lourd pèse comme un couvercle… »', 3),
    ('bdddbb2a-2331-50d4-be8a-fd976241211c'::uuid, '96deacc6-a828-5a10-a860-d3c1dc0cf8ba'::uuid, 'Que dit le poème « Correspondances » ?', 'mcq', '["La nature est un temple où parfums, couleurs et sons se répondent","La ville détruit la beauté","Le poète est un albatros","La mort est un voyage"]'::jsonb, 0, 'Le monde est « une forêt de symboles » que le poète déchiffre.', 4),
    ('ce8ebd55-ae52-55d1-b5e7-25a85df2cd7c'::uuid, '96deacc6-a828-5a10-a860-d3c1dc0cf8ba'::uuid, 'Quel est le dernier vers célèbre du recueil, dans « Le Voyage » ?', 'mcq', '["« Au fond de l’Inconnu pour trouver du nouveau ! »","« Ô mort, vieux capitaine »","« Là, tout n’est qu’ordre et beauté »","« Hypocrite lecteur, mon semblable, mon frère »"]'::jsonb, 0, 'La mort y est le dernier moyen d’échapper à l’ennui.', 5),
    ('dad5c8c8-a198-5b81-acea-1580f7381db3'::uuid, '96deacc6-a828-5a10-a860-d3c1dc0cf8ba'::uuid, 'Quelle est la particularité formelle du recueil ?', 'mcq', '["Une facture classique au service d’une matière scandaleuse","Le vers libre généralisé","L’absence de ponctuation","La prose exclusive"]'::jsonb, 0, 'Sonnets et alexandrins accueillent la charogne, la ville sale, la vieillesse.', 6),
    ('b574c8ac-1de1-597d-941a-ee56493c49c4'::uuid, '96deacc6-a828-5a10-a860-d3c1dc0cf8ba'::uuid, 'Les six pièces condamnées ont été réhabilitées du vivant de Baudelaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La condamnation ne sera annulée qu’en 1949.', 7),
    ('e3b110bb-aed7-544d-9c75-906c0fbfcc28'::uuid, '96deacc6-a828-5a10-a860-d3c1dc0cf8ba'::uuid, 'Combien de sections comporte l’édition de 1861 ?', 'mcq', '["Six","Quatre","Huit","Trois"]'::jsonb, 0, 'De Spleen et Idéal à La Mort, elles dessinent un itinéraire.', 8),
    ('139d9a83-ca47-54a1-8759-a4c79cd643a0'::uuid, 'd0768bf1-7e04-521b-9e51-69e70631a84f'::uuid, 'Quelle formule de Baudelaire résume le parcours ?', 'mcq', '["« Tu m’as donné ta boue et j’en ai fait de l’or »","« Je est un autre »","« La poésie doit être faite par tous »","« Il faut être absolument moderne »"]'::jsonb, 0, 'Elle vient d’un projet d’épilogue pour le recueil.', 1),
    ('f9eabceb-847b-58fb-83f6-77688919a468'::uuid, 'd0768bf1-7e04-521b-9e51-69e70631a84f'::uuid, 'Que démontre le poème « Une Charogne » ?', 'mcq', '["Que le sujet le plus repoussant peut produire un très beau poème","Que la nature est cruelle","Que l’amour est éternel par nature","Que la mort est belle"]'::jsonb, 0, 'La beauté n’est pas dans l’objet, mais dans la forme que lui donne le langage.', 2),
    ('b93012e0-0035-536c-8024-39977e5db21b'::uuid, 'd0768bf1-7e04-521b-9e51-69e70631a84f'::uuid, 'Qu’est-ce que le flâneur baudelairien ?', 'mcq', '["Celui qui trouve la beauté dans le passage, au cœur de la ville","Un poète retiré à la campagne","Un voyageur au long cours","Un critique d’art"]'::jsonb, 0, '« À une passante » en est l’exemple parfait.', 3),
    ('d605b8a4-3d07-5333-89a1-a7ad3960c533'::uuid, 'd0768bf1-7e04-521b-9e51-69e70631a84f'::uuid, 'Que sont les « deux postulations simultanées » ?', 'mcq', '["L’une vers Dieu, l’autre vers Satan","L’amour et la haine","La ville et la nature","Le passé et l’avenir"]'::jsonb, 0, 'Le recueil ne choisit pas : c’est cette tension qui le structure.', 4),
    ('51eebdd7-900e-5edf-8a8f-a0d79dffc32b'::uuid, 'd0768bf1-7e04-521b-9e51-69e70631a84f'::uuid, 'Dans quelle section se trouvent les poèmes sur la ville moderne ?', 'mcq', '["Tableaux parisiens","Le Vin","Révolte","La Mort"]'::jsonb, 0, 'Travaux, foules, vieillards, cygnes exilés : la boue y est urbaine.', 5),
    ('0019bb4a-de25-5da8-b2d5-24bd7983b7e3'::uuid, 'd0768bf1-7e04-521b-9e51-69e70631a84f'::uuid, 'Où réside la beauté selon l’alchimie baudelairienne ?', 'mcq', '["Dans le travail de la forme, non dans l’objet choisi","Dans la noblesse du sujet","Dans la sincérité du sentiment","Dans la musicalité seule"]'::jsonb, 0, 'C’est le renversement décisif de la poésie moderne.', 6),
    ('30e0caed-7063-51b3-a771-04e937227eb2'::uuid, 'd0768bf1-7e04-521b-9e51-69e70631a84f'::uuid, 'La modernité baudelairienne consiste à préférer la laideur à la beauté.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle consiste à transformer : c’est une esthétique de la transformation, pas de la laideur.', 7),
    ('86fe74e6-b4fe-5dbc-8aca-c41bb0adcd95'::uuid, 'd0768bf1-7e04-521b-9e51-69e70631a84f'::uuid, 'Quel poème évoque une inconnue croisée une seconde dans la rue ?', 'mcq', '["À une passante","Le Cygne","L’Albatros","Harmonie du soir"]'::jsonb, 0, 'L’amour y naît et se perd dans le même instant : c’est la beauté du transitoire.', 8),
    ('0ddf574f-ecfc-551f-891e-378fee75814f'::uuid, 'b78c0153-a61a-5dde-bd08-1aca282306fb'::uuid, 'Quelle décision Apollinaire prend-il sur les épreuves du recueil ?', 'mcq', '["Supprimer toute la ponctuation","Renoncer aux rimes","Classer les poèmes par date","Ajouter des illustrations"]'::jsonb, 0, '« Le rythme même et la coupe des vers, voilà la véritable ponctuation. »', 1),
    ('6e7cc9a4-e81e-5ce6-b2ba-744dd92e5c73'::uuid, 'b78c0153-a61a-5dde-bd08-1aca282306fb'::uuid, 'Quel poème ouvre le recueil ?', 'mcq', '["Zone","Le Pont Mirabeau","Vendémiaire","La Chanson du mal-aimé"]'::jsonb, 0, 'Il a pourtant été écrit en dernier : l’ordre du recueil est un choix esthétique.', 2),
    ('2247b6c7-f6e7-5aa2-814e-ae27505c3057'::uuid, 'b78c0153-a61a-5dde-bd08-1aca282306fb'::uuid, 'Par quel vers commence « Zone » ?', 'mcq', '["« À la fin tu es las de ce monde ancien »","« Sous le pont Mirabeau coule la Seine »","« Soleil cou coupé »","« Vienne la nuit sonne l’heure »"]'::jsonb, 0, 'Le poème se clôt sur « Soleil cou coupé ».', 3),
    ('708c1ee1-e399-50b7-b07a-240c49eacfa1'::uuid, 'b78c0153-a61a-5dde-bd08-1aca282306fb'::uuid, 'Quels éléments modernes entrent dans les poèmes ?', 'mcq', '["L’aviation, la publicité, la ville industrielle","Les mythes antiques seuls","Les paysages campagnards","Les batailles napoléoniennes"]'::jsonb, 0, 'Ils voisinent avec les chansons, les complaintes et les mythes rhénans.', 4),
    ('41a02be5-0d80-5535-afb7-18d45e3b9013'::uuid, 'b78c0153-a61a-5dde-bd08-1aca282306fb'::uuid, 'Que signifie le point d’interrogation du parcours « Modernité poétique ? »', 'mcq', '["La modernité d’Apollinaire est un alliage de tradition et d’invention","Le recueil n’est pas moderne","La modernité est un mot inventé après coup","Le recueil refuse toute nouveauté"]'::jsonb, 0, 'La modernité n’est pas la table rase : Apollinaire écrit aussi des vers d’une régularité parfaite.', 5),
    ('0a69986b-4f40-5e00-9a14-b9f9975e5bca'::uuid, 'b78c0153-a61a-5dde-bd08-1aca282306fb'::uuid, 'En quelle année Alcools paraît-il ?', 'mcq', '["1913","1900","1920","1857"]'::jsonb, 0, 'Le recueil rassemble des poèmes écrits sur une quinzaine d’années.', 6),
    ('a76afde9-c7bc-5b0a-83b2-720d255069b6'::uuid, 'b78c0153-a61a-5dde-bd08-1aca282306fb'::uuid, 'L’ordre des poèmes suit leur date de composition.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est délibérément désordonné, pour créer des échos plutôt qu’une progression.', 7),
    ('d0b1fb2c-bbad-5831-a48e-0fcf49c4813f'::uuid, 'b78c0153-a61a-5dde-bd08-1aca282306fb'::uuid, 'Que suggère le titre du recueil ?', 'mcq', '["Ce qui enivre, brûle et distille — des vies et des villes distillées","La fête et la boisson uniquement","La chimie moderne","Les cafés de Montmartre"]'::jsonb, 0, 'L’ivresse y est autant joie que douleur d’amour.', 8),
    ('09334f5f-a01b-5dc0-8b89-b07f05d9d648'::uuid, '1e9cdd79-5f1d-5f85-86c1-1f667034abd4'::uuid, 'Que signifie « moderne » appliqué à la poésie ?', 'mcq', '["Une manière de traiter le langage, pas une simple date","Un poème écrit après 1900","Un poème sans rime","Un poème engagé"]'::jsonb, 0, 'Le mot désigne une esthétique, pas une chronologie.', 1),
    ('deb57f16-43b4-59c4-859f-b85f2e71b9fa'::uuid, '1e9cdd79-5f1d-5f85-86c1-1f667034abd4'::uuid, 'Quelle formule Rimbaud emploie-t-il pour définir le poète ?', 'mcq', '["Un voyant, par un dérèglement raisonné de tous les sens","Un artisan du vers","Un prophète du peuple","Un peintre du réel"]'::jsonb, 0, 'Il demande aussi que la poésie soit « en avant ».', 2),
    ('0c9f3018-f21f-5b6e-8515-ac7812d656f0'::uuid, '1e9cdd79-5f1d-5f85-86c1-1f667034abd4'::uuid, 'Que dit Mallarmé de la fabrication des vers ?', 'mcq', '["« Ce n’est point avec des idées que l’on fait des vers, c’est avec des mots »","« Le poème est un miroir »","« Il faut chanter le peuple »","« La rime est une servitude »"]'::jsonb, 0, 'Le poème devient un objet verbal plutôt qu’un message.', 3),
    ('541b59dc-5118-5883-bc5a-43ddd07319f0'::uuid, '1e9cdd79-5f1d-5f85-86c1-1f667034abd4'::uuid, 'Quelle rupture Baudelaire introduit-il dès 1857 ?', 'mcq', '["Le beau sujet cesse d’exister : la ville et la laideur entrent dans le poème","Le vers libre","La suppression de la ponctuation","Le poème en prose exclusivement"]'::jsonb, 0, 'La beauté se déplace du sujet vers la forme.', 4),
    ('dd362bd6-4b11-58f9-9a89-f5d180f3b230'::uuid, '1e9cdd79-5f1d-5f85-86c1-1f667034abd4'::uuid, 'Comment évolue l’image poétique avec la modernité ?', 'mcq', '["Elle rapproche des réalités éloignées au lieu de comparer deux choses connues","Elle disparaît","Elle devient strictement descriptive","Elle se limite à la métaphore filée"]'::jsonb, 0, 'Les surréalistes systématiseront ce rapprochement après 1920.', 5),
    ('80196dbe-df66-5ee5-ad8b-e47ee275cb4d'::uuid, '1e9cdd79-5f1d-5f85-86c1-1f667034abd4'::uuid, 'Quel risque la modernité poétique fait-elle courir ?', 'mcq', '["L’hermétisme, qui perd le lecteur","La banalité","La censure systématique","La disparition du vers"]'::jsonb, 0, 'C’est ce que le point d’interrogation du parcours invite à peser.', 6),
    ('bd5b08f1-43d3-5d25-a8bf-76e231269779'::uuid, '1e9cdd79-5f1d-5f85-86c1-1f667034abd4'::uuid, 'Être moderne en poésie signifie forcément abandonner toute forme fixe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Apollinaire écrit des chansons régulières que tout le monde retient : la modernité est un alliage.', 7),
    ('8d0f4b2c-161e-5b85-83c1-8e6fb2066554'::uuid, '1e9cdd79-5f1d-5f85-86c1-1f667034abd4'::uuid, 'Quel changement la modernité impose-t-elle au lecteur ?', 'mcq', '["Il devient actif et doit choisir un sens parmi plusieurs","Il doit connaître la mythologie","Il doit lire à voix haute","Il doit suivre un ordre imposé"]'::jsonb, 0, 'La suppression de la ponctuation, chez Apollinaire, en est l’exemple le plus net.', 8),
    ('9c69ce3a-aea0-5adc-a246-1ce1daa5d747'::uuid, 'e27de7ac-ef29-5927-8ddc-871989a157ee'::uuid, 'De quoi Argan est-il malade ?', 'mcq', '["De rien : il est un malade imaginaire","D’une maladie pulmonaire","De la peste","D’une blessure ancienne"]'::jsonb, 0, 'Sa maladie est une obsession, entretenue par les médecins qui en vivent.', 1),
    ('d64690b6-7279-5c36-85b7-241e4832906c'::uuid, 'e27de7ac-ef29-5927-8ddc-871989a157ee'::uuid, 'Pourquoi Argan veut-il marier sa fille à Thomas Diafoirus ?', 'mcq', '["Pour avoir un médecin dans la famille","Pour rembourser une dette","Parce que Béline l’exige","Pour obtenir un titre de noblesse"]'::jsonb, 0, 'Angélique, elle, aime Cléante.', 2),
    ('bad6eadf-3839-529d-a020-3c094a143159'::uuid, 'e27de7ac-ef29-5927-8ddc-871989a157ee'::uuid, 'Quel stratagème permet de démasquer Béline ?', 'mcq', '["Argan fait semblant d’être mort","Toinette lit ses lettres","Béralde la fait suivre","Cléante la dénonce au notaire"]'::jsonb, 0, 'Elle se réjouit devant le corps, tandis qu’Angélique pleure.', 3),
    ('71f0a64a-64cf-5688-857a-c6918f3fb47f'::uuid, 'e27de7ac-ef29-5927-8ddc-871989a157ee'::uuid, 'Quel genre de pièce est Le Malade imaginaire ?', 'mcq', '["Une comédie-ballet, avec prologue et intermèdes chantés et dansés","Une tragi-comédie","Une farce en un acte","Un drame bourgeois"]'::jsonb, 0, 'La musique est de Marc-Antoine Charpentier.', 4),
    ('c721f9fb-c888-5e11-b863-d308637284d5'::uuid, 'e27de7ac-ef29-5927-8ddc-871989a157ee'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Par une cérémonie burlesque où Argan est reçu médecin en faux latin","Par la mort d’Argan","Par le mariage de Béline","Par le départ de Toinette"]'::jsonb, 0, '« Dignus, dignus est intrare » : la médecine y est réduite à un rituel.', 5),
    ('8c0fcfdd-e8b3-566d-b2f9-b3591d25290a'::uuid, 'e27de7ac-ef29-5927-8ddc-871989a157ee'::uuid, 'Que reproche Béralde à la médecine de son temps ?', 'mcq', '["De faire des cérémonies là où la nature guérit","D’être trop coûteuse seulement","De refuser les malades pauvres","De ne pas connaître la chirurgie"]'::jsonb, 0, 'C’est la médecine comme pouvoir qui est visée, non la science.', 6),
    ('be5223e6-0acd-599e-8255-a9142473ce9c'::uuid, 'e27de7ac-ef29-5927-8ddc-871989a157ee'::uuid, 'Molière est mort en scène pendant la première représentation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est pris de malaise lors de la quatrième représentation et meurt le soir même.', 7),
    ('c5158396-8cc7-5dca-9c85-4cb744d98987'::uuid, 'e27de7ac-ef29-5927-8ddc-871989a157ee'::uuid, 'Quel personnage se déguise en médecin de passage ?', 'mcq', '["Toinette","Béralde","Cléante","Angélique"]'::jsonb, 0, 'Le déguisement est le ressort comique et le moyen d’ouvrir les yeux d’Argan.', 8),
    ('4ed08077-51ec-5a04-b58e-bac7538045d1'::uuid, 'edfc860a-9535-5505-a80a-d53e281c87c4'::uuid, 'Qui organise le stratagème de la pièce ?', 'mcq', '["Dubois, l’ancien valet de Dorante","Marton","Madame Argante","Le comte Dorimont"]'::jsonb, 0, '« Nous sommes convenus de nos faits » : il conduit toute l’opération.', 1),
    ('2573a883-b686-5bff-872f-42d4208f720b'::uuid, 'edfc860a-9535-5505-a80a-d53e281c87c4'::uuid, 'Quelle est la situation de Dorante au début de la pièce ?', 'mcq', '["Il est ruiné et devient intendant chez Araminte","Il est un riche marchand","Il est officier","Il est le cousin d’Araminte"]'::jsonb, 0, 'Son absence de fortune est l’obstacle central.', 2),
    ('0e8ef002-ceb0-5fd6-a12f-d0fd74d98246'::uuid, 'edfc860a-9535-5505-a80a-d53e281c87c4'::uuid, 'Quelle « fausse confidence » Dubois fait-il à Araminte ?', 'mcq', '["Que Dorante est fou d’amour pour elle depuis qu’il l’a vue à l’Opéra","Que Dorante est riche","Que le comte est un escroc","Que Marton est amoureuse de Dorante"]'::jsonb, 0, 'La confidence est vraie, mais son moment et sa forme sont calculés.', 3),
    ('a2477848-1eef-5fa3-a529-6e9fe0c65ce6'::uuid, 'edfc860a-9535-5505-a80a-d53e281c87c4'::uuid, 'Quel objet compromet Dorante ?', 'mcq', '["Un portrait d’Araminte trouvé chez lui","Une bague","Un contrat de mariage","Une lettre de son père"]'::jsonb, 0, 'Il sert de preuve matérielle à l’amour que Dubois a annoncé.', 4),
    ('eb11ac8a-9878-5228-9afb-27153061732f'::uuid, 'edfc860a-9535-5505-a80a-d53e281c87c4'::uuid, 'Que fait Araminte pour éprouver Dorante ?', 'mcq', '["Elle lui dicte une lettre annonçant son propre mariage","Elle le congédie","Elle le présente à sa mère","Elle lui offre de l’argent"]'::jsonb, 0, 'La scène est cruelle : elle regarde souffrir celui qu’elle aime déjà.', 5),
    ('c6ad5617-a9ee-5351-81ff-00fedf684218'::uuid, 'edfc860a-9535-5505-a80a-d53e281c87c4'::uuid, 'Comment la pièce se termine-t-elle ?', 'mcq', '["Araminte avoue son amour et épousera Dorante malgré son absence de fortune","Araminte épouse le comte","Dorante quitte la maison","Marton épouse Dorante"]'::jsonb, 0, 'Un mariage socialement scandaleux, et c’est le sens du dénouement.', 6),
    ('02466d95-4bb7-5ef6-9d85-7b05d44ce02b'::uuid, 'edfc860a-9535-5505-a80a-d53e281c87c4'::uuid, 'Le marivaudage désigne un simple bavardage galant sans enjeu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une langue de l’aveu retardé, où chaque mot pèse socialement.', 7),
    ('e4f53c0f-3ab9-5442-9d82-b0832b885653'::uuid, 'edfc860a-9535-5505-a80a-d53e281c87c4'::uuid, 'En quelle année la pièce est-elle créée ?', 'mcq', '["1737","1730","1725","1750"]'::jsonb, 0, 'Elle est aujourd’hui l’une des pièces les plus jouées de Marivaux.', 8),
    ('afc3854d-09ab-50d2-b455-a419d258bfc9'::uuid, 'ef9587ad-6e6b-5674-b697-5332fc50130f'::uuid, 'Quelle position occupe Dubois dans la pièce ?', 'mcq', '["Celle d’un metteur en scène qui distribue les rôles et ménage ses effets","Celle d’un simple confident","Celle du rival de Dorante","Celle du narrateur"]'::jsonb, 0, 'Le stratagème devient ainsi une image du théâtre lui-même.', 1),
    ('41c5bb10-a39a-5fbb-999b-a50bd8977cd7'::uuid, 'ef9587ad-6e6b-5674-b697-5332fc50130f'::uuid, 'Quel argument soutient la lecture du stratagème comme révélation ?', 'mcq', '["Rien n’est inventé : Dorante aime vraiment, et Araminte l’aime déjà","Dubois avoue tout dès le début","Araminte connaissait le plan","Marton organise le dénouement"]'::jsonb, 0, 'Le stratagème lève des obstacles plutôt qu’il ne crée un sentiment.', 2),
    ('2f104c68-1297-5d2f-bc9f-42fd63e16683'::uuid, 'ef9587ad-6e6b-5674-b697-5332fc50130f'::uuid, 'Quel argument soutient la lecture du stratagème comme manipulation ?', 'mcq', '["Araminte est trompée et poussée pendant trois actes","Dorante ment sur son identité","Dubois vole une lettre","Le comte est calomnié"]'::jsonb, 0, 'La pièce donne des arguments aux deux lectures : c’est sa richesse.', 3),
    ('b6b8fab6-97d3-5a32-bf3c-a087c09baff4'::uuid, 'ef9587ad-6e6b-5674-b697-5332fc50130f'::uuid, 'Quel rôle joue l’argent dans la pièce ?', 'mcq', '["Il conditionne tous les rapports, jusqu’à l’aveu amoureux","Il n’intervient pas","Il n’intéresse que Marton","Il n’apparaît qu’au dénouement"]'::jsonb, 0, 'Chez Marivaux, l’amour n’est jamais hors du système social.', 4),
    ('332d6c48-0a1b-5dc9-8551-bdaecbbcfaab'::uuid, 'ef9587ad-6e6b-5674-b697-5332fc50130f'::uuid, 'Qu’est-ce que l’ironie dramatique dans cette pièce ?', 'mcq', '["Le spectateur connaît le stratagème avant Araminte","Les personnages parlent en aparté","Le dénouement est inattendu","Les valets se moquent des maîtres"]'::jsonb, 0, 'Le plaisir vient de voir le piège se refermer.', 5),
    ('072f973c-b8f4-522b-ba21-cd2928cbc3ef'::uuid, 'ef9587ad-6e6b-5674-b697-5332fc50130f'::uuid, 'Qui mène l’action au troisième acte ?', 'mcq', '["Araminte elle-même","Dubois seul","Madame Argante","Le comte Dorimont"]'::jsonb, 0, 'Elle éprouve Dorante et choisit son moment : elle n’est pas seulement agie.', 6),
    ('8d31b848-93dd-5897-8dc2-cab0f27a02e4'::uuid, 'ef9587ad-6e6b-5674-b697-5332fc50130f'::uuid, 'La pièce tranche clairement en faveur de la manipulation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle laisse les deux lectures ouvertes, ce qui en fait un sujet de dissertation classique.', 7),
    ('79e906b0-a39e-580e-a2fb-772c869ee1d2'::uuid, 'ef9587ad-6e6b-5674-b697-5332fc50130f'::uuid, 'Quel personnage veut marier Araminte au comte Dorimont ?', 'mcq', '["Madame Argante, sa mère","Marton","Dubois","Arlequin"]'::jsonb, 0, 'Elle veut un grand nom, ce qui rend le choix final d’Araminte plus fort.', 8),
    ('609596b0-5d4c-5f5c-8b52-07c1baaf89ba'::uuid, '69458436-36f7-5d79-9e0d-ef4fe52a36d8'::uuid, 'Pourquoi Louis revient-il dans sa famille ?', 'mcq', '["Pour annoncer sa mort prochaine","Pour demander de l’argent","Pour assister à un mariage","Pour vendre la maison"]'::jsonb, 0, 'Le prologue l’annonce au spectateur : « J’allais mourir à mon tour. »', 1),
    ('f1ddace0-3b75-5636-b53a-d5ee55aa3e30'::uuid, '69458436-36f7-5d79-9e0d-ef4fe52a36d8'::uuid, 'Depuis combien de temps Louis n’a-t-il pas vu sa famille ?', 'mcq', '["Environ douze ans","Deux ans","Six mois","Vingt-cinq ans"]'::jsonb, 0, 'Son absence est le grief principal d’Antoine.', 2),
    ('2e248e35-c780-531a-8431-641454f907bf'::uuid, '69458436-36f7-5d79-9e0d-ef4fe52a36d8'::uuid, 'Que se passe-t-il à la fin de la pièce ?', 'mcq', '["Louis repart sans avoir rien dit","Louis annonce sa mort à sa mère","Antoine part avec lui","La famille se réconcilie"]'::jsonb, 0, 'L’épilogue raconte au conditionnel un cri qu’il n’a jamais poussé.', 3),
    ('32e5a0f7-f12e-5d19-bc19-10c8020805cf'::uuid, '69458436-36f7-5d79-9e0d-ef4fe52a36d8'::uuid, 'Qui est Catherine ?', 'mcq', '["La belle-sœur de Louis, qu’il n’avait jamais rencontrée","La sœur de Louis","Sa mère","Une amie d’enfance"]'::jsonb, 0, 'Sa politesse gênée souligne l’étrangeté de la situation familiale.', 4),
    ('f8a0544e-4a21-59c8-958f-768342c8cd98'::uuid, '69458436-36f7-5d79-9e0d-ef4fe52a36d8'::uuid, 'Quelle est la particularité de la langue de Lagarce ?', 'mcq', '["Les phrases se reprennent et se corrigent en direct","Elle est en vers réguliers","Elle imite le langage juridique","Elle est très argotique"]'::jsonb, 0, 'On parle sans arrêt pour ne pas dire l’essentiel : la forme dit le sujet.', 5),
    ('8425c865-6d50-5fc8-8a4e-47ad3cbec26d'::uuid, '69458436-36f7-5d79-9e0d-ef4fe52a36d8'::uuid, 'Comment la pièce est-elle structurée ?', 'mcq', '["Prologue, deux parties séparées par un intermède, épilogue","Cinq actes","Trois actes et un final chanté","Une seule scène continue"]'::jsonb, 0, 'Il ne s’y passe presque rien : un déjeuner, des disputes, une promenade proposée.', 6),
    ('08de9d88-7419-5d0c-82d4-f4a5717df542'::uuid, '69458436-36f7-5d79-9e0d-ef4fe52a36d8'::uuid, 'La pièce comporte de nombreux rebondissements et coups de théâtre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’action est intérieure : c’est l’aveu impossible qui tient lieu d’intrigue.', 7),
    ('a760a489-2fae-526d-96bd-49d46be32573'::uuid, '69458436-36f7-5d79-9e0d-ef4fe52a36d8'::uuid, 'Que signifie le titre de la pièce ?', 'mcq', '["Une catastrophe intime réduite à une formule minimisée","Une prophétie religieuse","La fin d’une époque politique","Un titre ironique sans rapport avec l’intrigue"]'::jsonb, 0, 'La fin du monde, mais « juste » : et elle ne sera même pas dite.', 8),
    ('71e68608-bec3-5878-b007-0207c7ecdd2a'::uuid, '0cd3adc9-dbaf-5892-a006-1194eb4ecd98'::uuid, 'Pourquoi Louis ne parvient-il pas à parler ?', 'mcq', '["Annoncer sa mort reviendrait à demander quelque chose, ce qu’il n’a jamais fait","Sa famille l’en empêche physiquement","Il change d’avis dès le prologue","Il ne trouve pas le bon moment matériel"]'::jsonb, 0, 'Le silence final prolonge une vie tenue à distance.', 1),
    ('8c02ee78-1d61-5da1-81c4-9974ac1c49f4'::uuid, '0cd3adc9-dbaf-5892-a006-1194eb4ecd98'::uuid, 'Quel reproche Antoine adresse-t-il à son frère ?', 'mcq', '["D’avoir été le préféré, celui qui a pu partir","D’avoir volé de l’argent","De ne pas être venu à un enterrement","D’avoir menti sur son métier"]'::jsonb, 0, 'Il se dit « brutal » parce que c’est la place que la famille lui a laissée.', 2),
    ('f1f52640-974e-584f-987c-38e52dedb826'::uuid, '0cd3adc9-dbaf-5892-a006-1194eb4ecd98'::uuid, 'Comment la parole fonctionne-t-elle dans la pièce ?', 'mcq', '["Les monologues coexistent plus qu’ils ne dialoguent","Les personnages se répondent avec précision","Le dialogue est rapide et efficace","Les personnages parlent peu"]'::jsonb, 0, 'La langue échoue en parlant, et c’est cet échec qui émeut.', 3),
    ('7b5550ed-3a8e-51a6-bb74-d4732b28e60d'::uuid, '0cd3adc9-dbaf-5892-a006-1194eb4ecd98'::uuid, 'En quoi la pièce peut-elle être lue comme une tragédie ?', 'mcq', '["Destin annoncé dès le prologue, unités de lieu et de temps, héros prisonnier de ce qu’il est","Elle est écrite en alexandrins","Elle met en scène des rois","Elle se termine par un meurtre"]'::jsonb, 0, 'Ce qui manque, c’est le geste : la catastrophe est un non-événement.', 4),
    ('fcc4ac2a-52f8-561b-9b1b-9c66b6476146'::uuid, '0cd3adc9-dbaf-5892-a006-1194eb4ecd98'::uuid, 'Que fait La Mère pendant la visite ?', 'mcq', '["Elle rejoue le dimanche d’autrefois pour empêcher le pire","Elle interroge Louis sur sa santé","Elle reste silencieuse","Elle organise une fête"]'::jsonb, 0, 'Son bavardage est une digue contre ce qui menace d’être dit.', 5),
    ('55cd4dba-4683-5e77-a5df-5f5637f83076'::uuid, '0cd3adc9-dbaf-5892-a006-1194eb4ecd98'::uuid, 'Quel lien Suzanne entretenait-elle avec son frère ?', 'mcq', '["Elle ne le connaissait que par ses « petits mots »","Elle lui rendait visite chaque année","Elle vivait avec lui","Elle ne savait pas qu’il existait"]'::jsonb, 0, 'Ces messages laconiques sont au cœur de son reproche.', 6),
    ('5a6ed5c6-a7d2-58c0-bc02-3f0070b04840'::uuid, '0cd3adc9-dbaf-5892-a006-1194eb4ecd98'::uuid, 'La pièce tranche : Louis est présenté comme lâche.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le texte laisse ouverte l’hypothèse qu’il protège les siens en se taisant.', 7),
    ('6b33cd15-fad0-535c-b80c-19baa7cf36a3'::uuid, '0cd3adc9-dbaf-5892-a006-1194eb4ecd98'::uuid, 'Quelle formule revient constamment dans la bouche des personnages ?', 'mcq', '["« Ce que je veux dire, ce que je voulais dire »","« Nous verrons demain »","« Tout va bien »","« Il faut se parler »"]'::jsonb, 0, 'La reprise perpétuelle est la signature stylistique de Lagarce.', 8),
    ('8a4706de-2773-572d-94e8-099f85684cc9'::uuid, 'a2c731c3-77dc-5f4c-bbc1-e47c049ca0e0'::uuid, 'Sous quel pseudonyme Rabelais publie-t-il ?', 'mcq', '["Alcofribas Nasier, anagramme de son nom","Maître Janotus","Ponocrates","Frère Jean"]'::jsonb, 0, 'La prudence s’imposait face à la Sorbonne.', 1),
    ('5262a351-813e-57a8-bfc6-4b6a996a1ad0'::uuid, 'a2c731c3-77dc-5f4c-bbc1-e47c049ca0e0'::uuid, 'Que désigne la « substantifique moelle » ?', 'mcq', '["Le sens profond caché sous l’apparence comique","La recette d’un plat","Le contenu des Silènes antiques uniquement","Le résumé du livre"]'::jsonb, 0, 'Rabelais invite le lecteur à briser l’os pour en tirer le suc — tout en s’en amusant.', 2),
    ('a1ee5297-1c7b-5c3f-a140-84b6ce5cb21d'::uuid, 'a2c731c3-77dc-5f4c-bbc1-e47c049ca0e0'::uuid, 'Comment naît Gargantua ?', 'mcq', '["Par l’oreille de sa mère Gargamelle","D’un œuf","D’une fontaine","Dans une caverne"]'::jsonb, 0, 'Il crie aussitôt « À boire ! » : le gigantisme est comique et symbolique.', 3),
    ('bac73c92-1c49-5fa3-bef4-41178112bd69'::uuid, 'a2c731c3-77dc-5f4c-bbc1-e47c049ca0e0'::uuid, 'Quel précepteur humaniste réforme l’éducation de Gargantua ?', 'mcq', '["Ponocrates","Thubal Holoferne","Jobelin Bridé","Janotus de Bragmardo"]'::jsonb, 0, 'Journée réglée, exercice physique, lectures commentées : c’est le programme humaniste.', 4),
    ('97b71d3c-1ab6-5f5d-bab8-877e7bc156ee'::uuid, 'a2c731c3-77dc-5f4c-bbc1-e47c049ca0e0'::uuid, 'Quelle est l’origine de la guerre picrocholine ?', 'mcq', '["Une querelle de marchands de fouaces","Un mariage rompu","Un vol de terres","Une insulte religieuse"]'::jsonb, 0, 'L’absurdité de la cause souligne l’absurdité de la guerre de conquête.', 5),
    ('06975e99-bb95-50b3-8d4a-3b0bef59d483'::uuid, 'a2c731c3-77dc-5f4c-bbc1-e47c049ca0e0'::uuid, 'Quelle est la seule règle de l’abbaye de Thélème ?', 'mcq', '["« Fais ce que voudras »","« Prie et travaille »","« Silence et jeûne »","« Obéis à ton abbé »"]'::jsonb, 0, 'Anti-monastère mixte, sans horloge ni contrainte, réservé aux gens bien nés et bien instruits.', 6),
    ('03b8442b-d595-5a00-952e-f9d815f18538'::uuid, 'a2c731c3-77dc-5f4c-bbc1-e47c049ca0e0'::uuid, 'Le rire est chez Rabelais un simple divertissement sans portée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une méthode : il désacralise l’autorité, la scolastique et la guerre.', 7),
    ('4f8fe6cc-2ae5-5441-b340-85e66ef9d929'::uuid, 'a2c731c3-77dc-5f4c-bbc1-e47c049ca0e0'::uuid, 'Qui est Frère Jean des Entommeures ?', 'mcq', '["Un moine truculent qui défend l’abbaye et reçoit Thélème","Un précepteur sorbonnard","Le roi voisin de Grandgousier","Le père de Gargantua"]'::jsonb, 0, 'Il incarne l’action et le bon sens, contre la religion formaliste.', 8),
    ('5ef06de8-b363-5ea7-9fc7-252ff219eafc'::uuid, '25390193-d317-5c6e-83df-01e0cd7f287c'::uuid, 'Que propose le programme d’éducation de Ponocrates ?', 'mcq', '["Observation, exercice physique, lectures commentées, hygiène","Apprentissage par cœur et répétition","Retraite silencieuse au monastère","Formation militaire exclusive"]'::jsonb, 0, 'C’est le manifeste humaniste de l’homme complet, savant et sain.', 1),
    ('239004d6-dd53-570c-b291-874694122a56'::uuid, '25390193-d317-5c6e-83df-01e0cd7f287c'::uuid, 'Qui vient réclamer les cloches de Notre-Dame dans un discours ridicule ?', 'mcq', '["Janotus de Bragmardo","Ponocrates","Frère Jean","Picrochole"]'::jsonb, 0, 'La fausse logique de son discours est une satire de la scolastique.', 2),
    ('0a55269c-dd9a-5705-a333-99990bb50157'::uuid, '25390193-d317-5c6e-83df-01e0cd7f287c'::uuid, 'Quelle faute Picrochole commet-il ?', 'mcq', '["Il partage le monde avant d’avoir gagné une bataille","Il refuse de faire la guerre","Il épouse la fille de Grandgousier","Il fuit devant Frère Jean"]'::jsonb, 0, 'La scène est une satire de la démesure guerrière et des conseillers flatteurs.', 3),
    ('a85b3701-4913-500c-b117-d8a84a6c8eab'::uuid, '25390193-d317-5c6e-83df-01e0cd7f287c'::uuid, 'Comment nomme-t-on le rire rabelaisien, par le corps et le renversement des hiérarchies ?', 'mcq', '["Le rire carnavalesque","Le rire satirique","Le rire jaune","Le rire élégiaque"]'::jsonb, 0, 'La notion a été analysée par Bakhtine.', 4),
    ('833d22cb-8a58-5533-8c8d-aeefd797042a'::uuid, '25390193-d317-5c6e-83df-01e0cd7f287c'::uuid, 'Quelle limite l’utopie de Thélème présente-t-elle ?', 'mcq', '["Elle est réservée à des gens bien nés et bien instruits","Elle interdit les femmes","Elle impose un horaire strict","Elle exclut la lecture"]'::jsonb, 0, 'La liberté y est le fruit de l’éducation, pas un droit universel.', 5),
    ('2d4d6fa0-b353-5ddd-b66b-75c33fe2eaa5'::uuid, '25390193-d317-5c6e-83df-01e0cd7f287c'::uuid, 'Quel effet le rire produit-il sur l’autorité selon Rabelais ?', 'mcq', '["Il la désacralise et libère la pensée","Il la renforce","Il la laisse intacte","Il la remplace par une autre"]'::jsonb, 0, 'On ne discute pas une croyance dont on rit : on s’en libère.', 6),
    ('884a1d45-5cb5-5484-b40c-56200bd0c59d'::uuid, '25390193-d317-5c6e-83df-01e0cd7f287c'::uuid, 'Le rire chez Rabelais est une pause entre deux passages sérieux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est l’instrument même de la critique et rend le savoir désirable.', 7),
    ('b4dc2fd3-17cc-52d3-9a43-d6063f8bd184'::uuid, '25390193-d317-5c6e-83df-01e0cd7f287c'::uuid, 'Quel personnage plaide pour la paix contre la guerre de conquête ?', 'mcq', '["Grandgousier","Picrochole","Janotus","Gargamelle"]'::jsonb, 0, 'Sa lettre est l’une des grandes pages politiques du livre.', 8),
    ('4f5aca76-d344-5540-90ef-ed1b7270985a'::uuid, 'ef52987a-7bb1-5c60-977e-41bcfffb1d21'::uuid, 'Quelle forme prennent Les Caractères ?', 'mcq', '["Des remarques brèves : maximes, portraits, anecdotes","Un traité systématique","Un roman à intrigue","Un recueil de lettres"]'::jsonb, 0, 'Le livre se lit dans le désordre et se compose pourtant.', 1),
    ('6439fc4c-06be-5caa-ab4d-9ab8eea02c29'::uuid, 'ef52987a-7bb1-5c60-977e-41bcfffb1d21'::uuid, 'Que montre le portrait de Giton et Phédon ?', 'mcq', '["Que le corps et les manières trahissent la condition sociale","Que la richesse rend vertueux","Que la pauvreté est un choix","Que les nobles sont ridicules"]'::jsonb, 0, 'Giton est riche : il tousse, il occupe l’espace. Phédon est pauvre : il s’efface.', 2),
    ('ba71d339-c1f6-5bc3-a93e-b26cefdfa049'::uuid, 'ef52987a-7bb1-5c60-977e-41bcfffb1d21'::uuid, 'Quelle formule résume la cour selon La Bruyère ?', 'mcq', '["« L’on s’élève à la cour, mais on n’y monte pas »","« Tout est dit »","« Le cœur a ses raisons »","« Rien de trop »"]'::jsonb, 0, 'La cour est un pays étranger avec ses codes et ses langues.', 3),
    ('41ad3c82-c6ee-5b45-913d-e238541d990d'::uuid, 'ef52987a-7bb1-5c60-977e-41bcfffb1d21'::uuid, 'Quels livres le programme retient-il ?', 'mcq', '["Les livres V à X","Les livres I à IV","Le livre XI seul","Tous les livres"]'::jsonb, 0, 'De « De la société » à « Du souverain ou de la république ».', 4),
    ('f59fe77e-eb51-5ddb-b196-0d1c03459f3e'::uuid, 'ef52987a-7bb1-5c60-977e-41bcfffb1d21'::uuid, 'Pourquoi La Bruyère donne-t-il des noms grecs à ses personnages ?', 'mcq', '["Pour se protéger, tout en laissant reconnaître ses modèles","Par goût de l’Antiquité seule","Pour imiter Homère","Parce qu’il traduit des textes grecs"]'::jsonb, 0, 'Des « clés » circulaient pour identifier les modèles réels.', 5),
    ('d2394a86-f27c-58e9-b719-40c7b8f31d33'::uuid, 'ef52987a-7bb1-5c60-977e-41bcfffb1d21'::uuid, 'Quelle phrase ouvre l’œuvre ?', 'mcq', '["« Tout est dit, et l’on vient trop tard »","« Je chante l’homme »","« Le monde est un théâtre »","« Les hommes naissent libres »"]'::jsonb, 0, 'Elle justifie le choix du fragment et de la brièveté frappante.', 6),
    ('a887c19b-a8ea-5ae6-8966-d8399da5f4c3'::uuid, 'ef52987a-7bb1-5c60-977e-41bcfffb1d21'::uuid, 'La Bruyère démontre ses thèses par des raisonnements suivis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il montre plutôt qu’il ne démontre : un geste ou un vêtement suffisent à faire un caractère.', 7),
    ('a059dc55-a806-583d-a5b2-7a92a466566a'::uuid, 'ef52987a-7bb1-5c60-977e-41bcfffb1d21'::uuid, 'Quelle image saisissante La Bruyère donne-t-il des paysans ?', 'mcq', '["Des « animaux farouches » qui se révèlent hommes en se levant","Des enfants heureux","Des soldats en puissance","Des ombres invisibles"]'::jsonb, 0, 'C’est l’une des pages les plus fortes du livre X.', 8),
    ('26e28169-67e7-508e-b24e-212ed0c921b7'::uuid, '0d02f809-f06c-5d42-83e8-b10b27afc984'::uuid, 'À quel texte la Déclaration d’Olympe de Gouges répond-elle ?', 'mcq', '["À la Déclaration des droits de l’homme et du citoyen de 1789","Au Code civil","Au Contrat social de Rousseau","À la Constitution de 1791 seule"]'::jsonb, 0, 'Les femmes en étaient absentes : le pastiche rend cet oubli visible.', 1),
    ('553ac638-6e66-5ec0-b43d-aefd3d87434c'::uuid, '0d02f809-f06c-5d42-83e8-b10b27afc984'::uuid, 'Combien d’articles compte la Déclaration ?', 'mcq', '["Dix-sept","Dix","Trente","Cinq"]'::jsonb, 0, 'Exactement le même nombre que le texte de 1789, dans le même ordre.', 2),
    ('d301e3ce-6f03-54fc-b714-14d54ea1a8eb'::uuid, '0d02f809-f06c-5d42-83e8-b10b27afc984'::uuid, 'Que dit l’article X ?', 'mcq', '["La femme a le droit de monter sur l’échafaud, elle doit avoir celui de monter à la tribune","Toutes les femmes sont électrices","Le mariage est un contrat libre","L’instruction est due à toutes"]'::jsonb, 0, 'Punie comme citoyenne, la femme doit être représentée comme telle.', 3),
    ('5f5b1801-5dd4-556d-a78b-ae40b3d20334'::uuid, '0d02f809-f06c-5d42-83e8-b10b27afc984'::uuid, 'À qui la dédicace est-elle adressée ?', 'mcq', '["À la reine Marie-Antoinette","À l’Assemblée nationale","À Robespierre","Aux femmes du peuple"]'::jsonb, 0, 'Olympe de Gouges espérait un soutien venu du sommet.', 4),
    ('64b13c23-d1e0-5c8a-aad6-1aae8750cc18'::uuid, '0d02f809-f06c-5d42-83e8-b10b27afc984'::uuid, 'Quelle phrase ouvre le postambule ?', 'mcq', '["« Femme, réveille-toi ; le tocsin de la raison se fait entendre »","« Les hommes naissent libres et égaux »","« Écrasons l’infâme »","« Liberté, égalité, fraternité »"]'::jsonb, 0, 'Le registre change : il s’agit de convaincre les femmes elles-mêmes.', 5),
    ('732f7f6d-05a2-5df4-bf5f-a5715e0bb512'::uuid, '0d02f809-f06c-5d42-83e8-b10b27afc984'::uuid, 'Quel sort connut Olympe de Gouges ?', 'mcq', '["Elle fut guillotinée en 1793","Elle mourut en exil","Elle fut emprisonnée puis libérée","Elle vécut jusqu’à l’Empire"]'::jsonb, 0, 'L’article X en devient tragiquement prophétique.', 6),
    ('4a118bc5-a35f-5c82-a6e5-9b56b7273ccb'::uuid, '0d02f809-f06c-5d42-83e8-b10b27afc984'::uuid, 'La Déclaration a obtenu un effet légal immédiat.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les femmes n’obtiendront le droit de vote en France qu’en 1944.', 7),
    ('68688ab8-eac1-5286-b914-444dc9b86511'::uuid, '0d02f809-f06c-5d42-83e8-b10b27afc984'::uuid, 'Quel autre combat Olympe de Gouges a-t-elle mené ?', 'mcq', '["L’abolition de l’esclavage","La réforme de l’armée","La liberté du commerce","La séparation des Églises et de l’État"]'::jsonb, 0, 'Sa pièce L’Esclavage des Noirs le montre.', 8),
    ('87a60f94-ed50-5d13-869f-2e04440e8e7b'::uuid, '79f3984d-aab0-5cfc-b0ce-fcb95362e78d'::uuid, 'Pourquoi le pastiche de la Déclaration de 1789 est-il efficace ?', 'mcq', '["Il rend l’exclusion visible sans avoir à la démontrer","Il flatte les législateurs","Il simplifie le droit","Il évite la censure"]'::jsonb, 0, 'C’est une démonstration par la forme : le lecteur fait lui-même la comparaison.', 1),
    ('2a893c59-474a-5b9d-9eb4-2f5ce94c524b'::uuid, '79f3984d-aab0-5cfc-b0ce-fcb95362e78d'::uuid, 'À qui s’adresse le postambule ?', 'mcq', '["Aux femmes elles-mêmes","Au roi","Aux juges","Aux étrangers"]'::jsonb, 0, 'Apostrophes, impératifs et ironie : il s’agit de les réveiller.', 2),
    ('9b7a80f9-75d5-53d8-ab03-292df772e7c9'::uuid, '79f3984d-aab0-5cfc-b0ce-fcb95362e78d'::uuid, 'Que propose le contrat social entre l’homme et la femme ?', 'mcq', '["Le partage des biens et la reconnaissance des enfants naturels","La suppression du mariage","Le vote des femmes uniquement","L’égalité salariale"]'::jsonb, 0, 'C’est la partie la plus concrète et la plus juridique du texte.', 3),
    ('d3bfdec9-4f2d-5e30-aacd-5605a8eeca8e'::uuid, '79f3984d-aab0-5cfc-b0ce-fcb95362e78d'::uuid, 'Quelles égalités le texte réclame-t-il ?', 'mcq', '["Politique, civile et d’expression","Seulement politique","Seulement économique","Seulement dans l’éducation"]'::jsonb, 0, 'Un programme complet, réalisé seulement au XXe siècle.', 4),
    ('fed50947-d43c-5151-8f40-84581854d6a6'::uuid, '79f3984d-aab0-5cfc-b0ce-fcb95362e78d'::uuid, 'Quelle limite peut-on relever dans le texte ?', 'mcq', '["Il s’adresse d’abord aux femmes instruites et garde un vocabulaire de la « nature » féminine","Il refuse le droit de vote","Il défend l’esclavage","Il ignore la question du mariage"]'::jsonb, 0, 'Ces tensions situent le texte dans son époque : un bon devoir les mentionne.', 5),
    ('ec3d9919-5d0c-5c9a-b335-a4b662eca36f'::uuid, '79f3984d-aab0-5cfc-b0ce-fcb95362e78d'::uuid, 'Quel est l’effet politique immédiat de la Déclaration ?', 'mcq', '["Presque aucun : elle est ignorée en 1791","Elle est votée par l’Assemblée","Elle inspire la Constitution de 1793","Elle obtient le droit de vote"]'::jsonb, 0, 'Elle change pourtant ce qui peut être dit — et elle est aujourd’hui au programme.', 6),
    ('a4584136-2365-572d-8e65-d5185fa6a401'::uuid, '79f3984d-aab0-5cfc-b0ce-fcb95362e78d'::uuid, 'Le registre du texte est uniforme du début à la fin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Juridique dans les articles, polémique dans le postambule, didactique dans le contrat social.', 7),
    ('013da1b6-852e-570b-9640-9deb4909ecdb'::uuid, '79f3984d-aab0-5cfc-b0ce-fcb95362e78d'::uuid, 'Que prouve le destin d’Olympe de Gouges quant au parcours ?', 'mcq', '["Qu’écrire pour l’égalité pouvait coûter la vie","Que la Révolution soutenait les femmes","Que le texte fut aussitôt appliqué","Que l’écriture est sans risque"]'::jsonb, 0, 'Guillotinée en 1793 : l’écriture fut bien un combat.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 260 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 260 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
